[436]={["atomIDs"]={"436:description:1-79","436:description:82-171","436:description:176-285","436:description:290-347","436:description:350-421","436:description:426-511","436:objective:1-28"},["opening"]="Ironband's excavation east of the lake was progressing too slowly for Jern's comfort. The volume of supplies sent there made the delay troubling, and Magmar Fellhew managed the details that might explain it.",["pending"]="{actor} intended to ask Explorer Fellhew about the excavation's slow progress.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} consulted Magmar Fellhew at Ironband's excavation.",["sourceHash"]="238c47d8343b779c2017db16644c08be3f427587628e6e6ab2fb43a00e51dcd2",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[437]={["atomIDs"]={"437:description:1-119","437:description:122-261","437:description:266-293","437:description:298-345","437:description:348-433","437:description:438-467","437:description:470-497","437:objective:1-40","437:objective:45-77","437:objective:82-153"},["opening"]="Assaults on the Dead Fields had failed whenever Nightlash reinforced the gnolls. Hadrec sought the banshee's essence as proof that this defense was broken.",["pending"]="{actor} planned to confront Nightlash at the farm.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Nightlash's essence to Hadrec.",["sourceHash"]="75dc52c2dd51c80c5284aa0fdd3252d58096e277d579cad537dda936679b31c6",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[438]={["aftermath"]="The boat held wrapped corpses, and another dock was visible across the lake on Fenris Isle.",["atomIDs"]={"438:description:1-68","438:description:71-163","438:description:168-231","438:description:234-297","438:objective:1-25","438:objective:30-73"},["endingAtomIDs"]={"438:completion:1-53","438:completion:55-138","438:completion:143-190"},["opening"]="Hadrec had discovered another Scourge gathering at the ferry. Heavy patrols concealed a purpose his scouts had not yet learned.",["pending"]="{actor} meant to investigate the occupied crossing.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the search at the ferry.",["sourceHash"]="80acf1b91d68e88a24f5b93c1ce0d25344cb30c4d3c974c5c47865ebaf9435f2",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[439]={["aftermath"]="Hadrec inferred that Tirisfal's mass graves supplied the bodies being taken to Fenris Isle.",["atomIDs"]={"439:description:1-46","439:description:49-123","439:description:130-151","439:description:154-210","439:description:215-226","439:objective:1-61"},["endingAtomIDs"]={"439:completion:1-60","439:completion:65-139","439:completion:141-204"},["opening"]="A woman's relatively fresh hand protruded from the wrapped bodies. Its ring bore Deliah's name, providing a clue to the shipment's origin.",["pending"]="{actor} intended to show the ring to Hadrec.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the ring to Hadrec.",["sourceHash"]="6a10e726d9629e8beb3b6acbec6c66bbd42200dc30f5b54a4011e6db3099a2c0",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[440]={["aftermath"]="Sevren confirmed that a Deliah from Brill had been buried in the mass grave.",["atomIDs"]={"440:description:1-70","440:description:72-114","440:description:117-199","440:description:204-223","440:description:226-268","440:description:271-329","440:objective:1-50"},["endingAtomIDs"]={"440:completion:1-40","440:completion:42-181","440:completion:186-240","440:completion:242-290"},["opening"]="Hadrec suggested that Brill's death records might identify Deliah. He offered little hope that the person who gave her the ring would still care.",["pending"]="{actor} planned to seek Deliah's identity through Sevren.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} presented Deliah's ring to Sevren.",["sourceHash"]="b7ccbff139d2355ff85781b68bb74a2e2155ff796c8a19291360c21aef846153",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[441]={["aftermath"]="Raleigh recognized his wife's ring. He denied lingering grief but spoke of a desire for revenge.",["atomIDs"]={"441:description:1-63","441:description:66-153","441:description:158-206","441:objective:1-31"},["endingAtomIDs"]={"441:completion:1-29","441:completion:31-96","441:completion:98-178","441:completion:183-233","441:completion:235-282","441:completion:287-305"},["opening"]="Sevren had found a possible surviving connection in Deliah's husband. Raleigh now lived in the Undercity and might identify the ring conclusively.",["pending"]="{actor} meant to carry the ring to Raleigh.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the ring to Raleigh.",["sourceHash"]="a04c5e3e2ea12fa31eef708c398731adc77333eaadeb6958f68208457cfcd730",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[442]={["aftermath"]="Hadrec reported that Renferrel had felt the released energies as far away as the Sepulcher.",["atomIDs"]={"442:description:1-86","442:description:91-148","442:description:151-166","442:description:171-218","442:description:221-238","442:objective:1-60"},["endingAtomIDs"]={"442:completion:1-52","442:completion:54-163","442:completion:168-219","442:completion:221-243"},["opening"]="Hadrec ordered an assault on Fenris Isle's leader. Thule's head was the proof required from the Scourge stronghold.",["pending"]="{actor} intended to confront Thule on the isle.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Thule's head to Hadrec.",["sourceHash"]="94c55ed092fb0f61aee40236b548a533b1d33c70ffc4c89203a116bf0e148ca8",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[443]={["atomIDs"]={"443:description:1-96","443:description:99-198","443:description:203-307","443:description:310-375","443:objective:1-75"},["opening"]="The apothecaries wanted to understand the island's gnolls before a direct assault. Their strange ichor might expose the origin of the Rot Hides.",["pending"]="{actor} planned to gather eight bottles for Renferrel.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the ichor to Renferrel.",["sourceHash"]="29ecd187696965b4b79e5dd1bbda3841db6d1b36b6f015b5f9432b28e3df2e56",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[444]={["aftermath"]="Bethor recognized spells unseen for a long time and prepared a divination.",["atomIDs"]={"444:description:1-82","444:description:85-208","444:description:213-313","444:description:316-420","444:description:430-488","444:objective:1-59"},["endingAtomIDs"]={"444:completion:1-100","444:completion:105-156"},["opening"]="Renferrel had detected warlock and necromantic magic, but his findings remained inconclusive. Bethor's knowledge might resolve what the sample still concealed.",["pending"]="{actor} meant to take the sample to Bethor.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} placed the sample in Bethor's hands.",["sourceHash"]="f322aad1a76dfa9d5f925126f6996a819588b2c84688cd2d332751d23ec47760",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[445]={["atomIDs"]={"445:description:1-87","445:description:90-117","445:description:122-328","445:description:333-431","445:description:434-474","445:description:477-508","445:objective:1-79"},["opening"]="Johaan's findings belonged to the Society's shared work toward Sylvanas's desired plague. Renferrel awaited that research in Silverpine.",["pending"]="{actor} intended to deliver Johaan's findings.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the research to Renferrel.",["sourceHash"]="8483a2925e41f1a29f641462822dde54a5201fdd45aba40f194db2d931a76ffe",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[446]={["aftermath"]="Renferrel recognized powerful magic in the scroll and anticipated a potent mixture against Thule.",["atomIDs"]={"446:description:1-68","446:description:71-214","446:description:219-311","446:description:316-388","446:description:391-436","446:description:439-484","446:objective:1-74"},["endingAtomIDs"]={"446:completion:1-41","446:completion:43-85","446:completion:87-200"},["opening"]="Bethor identified his former colleague Thule as the ichor's maker. His familiarity with those spells offered Renferrel a possible countermeasure.",["pending"]="{actor} planned to carry Bethor's incantations south.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Bethor's scroll to Renferrel.",["sourceHash"]="356fbca8ee022cbce697a622ce58b2c0f9c9b6bd83645bedfde623a3eda3393f",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[448]={["atomIDs"]={"448:description:1-76","448:description:79-138","448:objective:1-48"},["opening"]="Renferrel directed the planned assault through Hadrec first. The executor might have information or equipment needed before Fenris Isle could be attacked.",["pending"]="{actor} meant to consult Hadrec before the assault.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported to Hadrec at the Sepulcher.",["sourceHash"]="c26277c3a0a41c3edbb1618153c09d1256cffc8cb53342bc0306703902598f56",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[449]={["aftermath"]="Hadrec acknowledged that Scourge strength and the scouts' difficulties had exceeded his expectations.",["atomIDs"]={"449:description:1-109","449:description:112-187","449:objective:1-71"},["endingAtomIDs"]={"449:completion:1-160","449:completion:165-213","449:completion:215-240"},["opening"]="Rane wanted the reconnaissance delivered while Quinn's wounds mended. The report held information she considered vital to the occupation of Silverpine.",["pending"]="{actor} intended to carry the scouts' report.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Deathstalker report to Hadrec.",["sourceHash"]="2a601f56899c7e758da5bba66ca5b62305a26201bd916172a0a2818618158d45",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[452]={["aftermath"]="Faerleia hoped the council's death would open a path to control of Pyrewood; that outcome remained uncertain.",["atomIDs"]={"452:description:1-42","452:description:47-96","452:description:99-146","452:description:149-243","452:description:246-360","452:description:365-399","452:description:402-423","452:description:426-484","452:objective:1-53"},["endingAtomIDs"]={"452:completion:1-53","452:completion:55-173","452:completion:175-187"},["opening"]="Faerleia awaited the returning council and hoped its removal might turn Arugal's followers against him. She could not face the group alone.",["pending"]="{actor} planned to help Faerleia confront the council.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the defense against the Pyrewood Council.",["sourceHash"]="2a04280c4dfb18e39a941d08b6bc6cf45f6ec9609d647b59963bb84f9ad55f66",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[453]={["atomIDs"]={"453:description:17-72","453:description:77-162","453:objective:1-24","453:objective:27-37","453:objective:42-71","453:objective:76-107","453:objective:112-145"},["opening"]="The clues described a nervous outsider who left Darkshire heading west. Smitts feared that a man seeking refuge beyond the town's protection might have become prey himself; the search had to follow that westward trail.",["pending"]="{actor} planned to seek the nervous stranger who traveled west from Darkshire.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Jitters, the shadowy figure sought through the book.",["sourceHash"]="e106ddc02934accae79402455bf4d109ff0af1b9fba326421e8ab07e21e9c349",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[454]={["atomIDs"]={"454:description:1-78","454:description:80-88","454:description:90-187","454:description:192-264","454:description:266-332","454:objective:1-17"},["opening"]="The powder carriers had divided their work after the ambush. Huldar watched the remaining barrels while Miran hauled the shipment, a task he did not want his companion attempting unguarded.",["pending"]="{actor} meant to speak with Miran about accompanying his next trip.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Miran about the remaining powder delivery.",["sourceHash"]="29334d5a2639805be02a39ea098adfd6b0fc54de6905e8569227e576571f45a5",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[455]={["atomIDs"]={"455:description:1-56","455:description:59-100","455:description:103-237","455:description:242-325","455:description:328-372","455:description:377-456","455:description:461-486","455:description:489-500","455:objective:1-19","455:objective:24-70","455:objective:75-119"},["opening"]="Dragonmaw orcs had expanded into Dun Algaz, threatening the connection between Loch Modan and Menethil Harbor. Rockgar needed a passage forced through the occupied route and a report carried to Valstag Ironjaw.",["pending"]="{actor} would traverse Dun Algaz, meet the scout-and-grunt assignment and report to Valstag.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Dun Algaz assignment against eight Dragonmaw Scouts and six Grunts and reported to Valstag Ironjaw.",["sourceHash"]="524fc92094783dd80c19c622aad1bc8823e273df6cb37f75623f64b57af86ca8",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[460]={["aftermath"]="Alaric confirmed that the gnolls had not destroyed his body.",["atomIDs"]={"460:description:1-31","460:description:34-38","460:description:41-58","460:description:63-131","460:description:134-262","460:description:265-331","460:description:333-378","460:description:383-409","460:description:412-501","460:objective:1-33"},["endingAtomIDs"]={"460:completion:1-14","460:completion:16-57","460:completion:59-90"},["opening"]="Alaric said Thule's protection had trapped him in undeath before his beheading. He believed his body remained buried near the keep's stable.",["pending"]="{actor} meant to carry Alaric's head to its grave.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Alaric's head to his grave.",["sourceHash"]="428e6f01462674b8a1a6fde7f9751dd88183765026507e643eaea03405fbd50d",["sourceRaceMask"]="690",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[461]={["aftermath"]="Alaric opened the niche and asked to remain within the keep, hidden from the Rot Hides.",["atomIDs"]={"461:description:1-98","461:description:101-146","461:description:149-162","461:description:167-240","461:description:245-277","461:description:280-306","461:objective:1-33"},["endingAtomIDs"]={"461:completion:1-24","461:completion:26-39","461:completion:41-148","461:completion:153-228","461:completion:233-250","461:completion:252-268"},["opening"]="Alaric knew a concealed alcove behind a shelf in the southwestern tower. He offered to open it if his body was carried there.",["pending"]="{actor} intended to bring Alaric to the hidden alcove.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Alaric to the alcove.",["sourceHash"]="4a143a93e7917f4067e60ee7c00ca4f38e5376dd6d2f6f1647cbd6834ae04964",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[463]={["atomIDs"]={"463:description:1-32","463:description:35-70","463:description:73-158","463:description:163-269","463:description:272-318","463:description:323-348","463:description:351-483","463:objective:1-21"},["opening"]="Fitzsimmons placed the Greenwarden in the marsh east of the Dun Modr road fork. The sailor's directions came wrapped in grim jokes about the creatures surrounding the elusive being.",["pending"]="{actor} planned to seek the Greenwarden in the Wetlands marsh.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Rethiel the Greenwarden.",["sourceHash"]="6430466dae12c93d1b42d9db7ae908fc5b369867ca51d45875995274139a9bb4",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[464]={["atomIDs"]={"464:description:1-124","464:description:127-217","464:description:220-310","464:description:315-388","464:description:393-430","464:description:433-479","464:objective:1-51"},["opening"]="Stoutfist described a Dragonmaw remnant driven from Grim Batol after losing its red dragons. The clan had regained strength northeast of Menethil; eight war banners would provide evidence of an attack on its camp.",["pending"]="{actor} meant to recover eight Dragonmaw War Banners for Stoutfist.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered eight Dragonmaw War Banners to Captain Stoutfist.",["sourceHash"]="e527556b5812e30bd542f142940276b7a1dea804db0869960114a4d969dff5b8",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[465]={["atomIDs"]={"465:description:1-74","465:description:79-141","465:description:144-225","465:description:230-266","465:description:269-304","465:description:309-331","465:description:334-396","465:description:401-451","465:description:454-508","465:objective:1-32"},["opening"]="Stoutfist had learned that Nek'rosh intended to besiege Menethil with catapults. With Algaz cutting off reinforcements, the captain supplied tinder for an attack on the siege engines in the Dragonmaw camp.",["pending"]="{actor} would burn the Dragonmaw catapults with Stoutfist's tinder.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the destruction assignment against the Dragonmaw catapults.",["sourceHash"]="4bb00cf6a37997d979e4f46d767449168327fdb033e7559498d3d5247bb3ce59",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[466]={["atomIDs"]={"466:description:1-99","466:description:102-272","466:description:277-356","466:description:361-428","466:description:431-460","466:description:462-498","466:objective:1-66"},["opening"]="Stonegear had heard of incendicite in a Wetlands cave northwest of Algaz Gate. The volatile ore might produce stronger cannon shells if someone could smelt it safely; extracting six loads would require mining skill.",["pending"]="{actor} would obtain six loads of Incendicite Ore for Stonegear.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered six loads of Incendicite Ore to Pilot Stonegear.",["sourceHash"]="1a0a103bfe378882053e2977f15117ea3a221b5b0762318a70cd3302cf5405a7",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[467]={["atomIDs"]={"467:description:1-62","467:description:65-135","467:description:140-220","467:description:223-336","467:objective:1-27"},["opening"]="Stonegear was seeking a rare ore that might improve his siege engine's firepower. Kadrell directed an interested traveler back to Steelgrill's Depot to hear the pilot's proposal.",["pending"]="{actor} meant to speak with Pilot Stonegear about the rare ore.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Pilot Stonegear about his search.",["sourceHash"]="8549e0313549c09ec0857172ef716496e8b5d98a8dde2fc2d80f88fc80feada2",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[468]={["atomIDs"]={"468:description:1-100","468:description:107-212","468:description:215-269","468:objective:1-31"},["opening"]="Rockgar sought volunteers for a mission through Dun Algaz into the Wetlands. Kadrell directed prospective help north along the road beyond the guard tower.",["pending"]="{actor} would meet Mountaineer Rockgar at Dun Algaz.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Mountaineer Rockgar about the Wetlands mission.",["sourceHash"]="579e9f0497657ad0504046afd46e120f23a56f89496e742a78a0e6a3c6bafc21",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[469]={["atomIDs"]={"469:description:1-20","469:description:25-99","469:description:101-210","469:description:215-375","469:description:380-495","469:objective:1-88"},["opening"]="Einar's bundle of crocolisk skins was ready for the Menethil tanner. A traveler heading to the harbor could keep the trade moving while the hunter put off an awkward return home.",["pending"]="{actor} intended to carry Einar's Bundle of Crocolisk Skins to James Halloran.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Bundle of Crocolisk Skins to James Halloran in Menethil.",["sourceHash"]="adbbc85273a53ca247971d63e8e6297d0145cecaaa1e06de1f6e4b9b903120fe",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[470]={["atomIDs"]={"470:description:1-82","470:description:84-105","470:description:110-158","470:description:160-194","470:description:196-243","470:description:248-312","470:description:317-384","470:description:386-438","470:description:440-457","470:objective:1-109"},["opening"]="An ooze swallowed Sida's bag when she threw it during an attack at Ironbeard's Tomb. She escaped but could not tell which creature took the belongings she now needed recovered.",["pending"]="{actor} meant to recover Sida's bag from the oozes at Ironbeard's Tomb.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Sida's bag to her in Menethil Harbor.",["sourceHash"]="cfe8dbd6b48d7215847de42327cb6f7206d7c5e93fbc391a98b8051962ced6ef",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
