[472]={["atomIDs"]={"472:description:1-45","472:description:50-73","472:description:76-107","472:description:110-194","472:description:199-246","472:description:249-305","472:description:308-322","472:description:327-385","472:description:388-414","472:description:417-449","472:description:452-493","472:objective:1-47"},["opening"]="Wounded Harlo Barnaby remembered the Dark Iron assault after the Thandol ambush and Longbraid sounding the retreat. He awoke in Menethil without knowing whether his commander survived.",["pending"]="{actor} planned to search near Dun Modr for Longbraid.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Longbraid near Dun Modr.",["sourceHash"]="f7184ebfb952f16670049fdfbb9736af5059fe05e05791ea69b39365577837af",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[473]={["atomIDs"]={"473:description:6-76","473:description:79-166","473:description:169-207","473:objective:1-29"},["opening"]="Valstag warned that the Dragonmaw threat reached beyond Algaz. Captain Stoutfist was seeking assistance in the keep's war room, where the wider campaign could be explained.",["pending"]="{actor} would report to Captain Stoutfist.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Captain Stoutfist about the Dragonmaws.",["sourceHash"]="34bdac1645ada41117350efa2ca4d0aa78771f05d9e85b2a4a12fcef01c7c2c8",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[474]={["atomIDs"]={"474:description:1-74","474:objective:1-23","474:objective:28-70"},["opening"]="With the catapults burned, the orders turned to their master. Chieftain Nek'rosh was the remaining target, and his head was to be brought to Captain Stoutfist.",["pending"]="{actor} would confront Chieftain Nek'rosh and return his head to Stoutfist.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against Chieftain Nek'rosh and delivered his head to Stoutfist.",["sourceHash"]="555e1798231650d76cc49f95fc4cb816e7dfb9e84f15cc6dcd3781f4d208fe28",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[475]={["atomIDs"]={"475:description:1-44","475:description:49-158","475:description:161-283","475:description:288-344","475:description:347-500","475:objective:1-51"},["opening"]="Athridas worried that Gaerolas had fallen silent. As Great Warden of the sleeping Druids of the Talon, Gaerolas safeguarded their rest and their pact with Ysera; his delayed word called for a visit to Starbreeze Village.",["pending"]="{actor} planned to seek Gaerolas Talvethren in Starbreeze Village.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Gaerolas Talvethren in Starbreeze Village.",["sourceHash"]="75434eb6abd9ac836b269d56374c34cf47a92a0d0c15c83cf00f12fd4ebcb245",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[477]={["aftermath"]="The opened crate contained old regional maps and a magical pendant beneath them.",["atomIDs"]={"477:description:1-145","477:description:150-302","477:description:307-363","477:description:365-436","477:description:438-492","477:objective:1-60","477:objective:62-105"},["endingAtomIDs"]={"477:completion:1-86","477:completion:88-231","477:completion:236-296"},["opening"]="Shipments had passed from Hillsbrad toward Ambermill and a camp near Pyrewood. Allister suspected a purpose beyond support for an obscure village.",["pending"]="{actor} planned to inspect a wizard shipment's crate.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} opened one of the Dalaran supply crates.",["sourceHash"]="f483ebcaf4ef2ba39aa736a43cfd7109a6b5e69800d825292a34787cc0dac9d0",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[478]={["aftermath"]="Maps and pendant left Allister uncertain of Dalaran's aim; he proposed consulting Dalar.",["atomIDs"]={"478:description:1-68","478:objective:1-69"},["endingAtomIDs"]={"478:completion:1-16","478:completion:18-29","478:completion:31-42","478:completion:47-168","478:completion:173-219"},["opening"]="The pendant had been removed from the shipment. Allister needed the object before he could judge what the wizards were preparing.",["pending"]="{actor} meant to bring the strange pendant to Allister.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the pendant to Allister.",["sourceHash"]="585da75eab1f0b693777ffbf1a8a1a219d041ef24228802ed4b58e9f5d4c63a2",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[479]={["aftermath"]="Allister reported that the weaving remained advanced and a powerful wizard guided it.",["atomIDs"]={"479:description:1-70","479:description:72-134","479:description:139-209","479:description:211-235","479:description:240-300","479:objective:1-70"},["endingAtomIDs"]={"479:completion:1-73","479:completion:78-129","479:completion:131-157"},["opening"]="Dalar was searching for the spellcasting's source while Allister sought delay. Pendants carried by Ambermill's wizards provided an immediate target.",["pending"]="{actor} intended to recover eight wizard pendants.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought eight pendants to Allister.",["sourceHash"]="d37e6f8cacf21757409c737ac3ba86329647a114bd201f7849bc31f4100a539b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[480]={["aftermath"]="Allister reported that the magic dissipated and the ley energies returned to dormancy, though the nearby power remained a concern.",["atomIDs"]={"480:description:1-81","480:description:83-165","480:description:167-245","480:description:250-296","480:description:298-340","480:description:342-348","480:objective:1-95"},["endingAtomIDs"]={"480:completion:1-77","480:completion:79-204","480:completion:209-292","480:completion:294-327"},["opening"]="An archmage directed the awakening of Ambermill's ley node. Allister considered his removal the remaining way to interrupt the work.",["pending"]="{actor} planned to confront the archmage and recover his staff.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the archmage's staff to Allister.",["sourceHash"]="d748d3cfafb355ad91120faf62452c6e72416a20f587688a6d7c5b08cd0e2dc1",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[481]={["aftermath"]="Dalar recognized an energy-channeling artifact and suspected a project of considerable scale.",["atomIDs"]={"481:description:1-91","481:objective:1-69"},["endingAtomIDs"]={"481:completion:1-63","481:completion:65-92","481:completion:94-181","481:completion:186-298","481:completion:303-370"},["opening"]="Allister sought Dalar's reading of the rune-marked pendant. The artifact offered a possible explanation for the shipments into Ambermill.",["pending"]="{actor} meant to seek Dalar's analysis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} showed the pendant to Dalar.",["sourceHash"]="35f2a9c534879bcfba43c30eb815f20a9e72f1e807bb951122986dab3092fc55",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[482]={["atomIDs"]={"482:description:1-10","482:description:12-38","482:description:43-151","482:description:153-250","482:description:255-287","482:description:292-428","482:description:433-502","482:objective:1-51"},["opening"]="Dalar remembered the dormant ley node beneath Ambermill. He inferred that the wizards planned to awaken it and that lost pendants could delay the work.",["pending"]="{actor} intended to relay Dalar's finding to Allister.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} carried Dalar's warning to Allister.",["sourceHash"]="da845d5dd9985173047a46c8dad57961d6de9e131fd5a9bb23eeff40e8f72eca",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[484]={["atomIDs"]={"484:description:1-31","484:description:33-136","484:description:141-150","484:description:152-213","484:description:218-283","484:description:288-362","484:description:364-429","484:objective:1-69"},["opening"]="Halloran shipped cured crocolisk leather to distant ports, but his stock of softer young skins was low. The marshes just outside Menethil supplied the four skins he sought.",["pending"]="{actor} would obtain four Young Crocolisk Skins for Halloran.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied James Halloran with four Young Crocolisk Skins.",["sourceHash"]="997f8d24d0f15194f0f244aee49ec9b5bc1539ed4a8f765b46dc3300b93553f7",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[485]={["aftermath"]="The machine stood again but needed major repairs and was too heavy to carry.",["atomIDs"]={"485:description:1-75","485:description:78-194","485:description:197-249","485:description:254-318","485:description:321-394","485:description:399-510","485:objective:1-115"},["endingAtomIDs"]={"485:completion:1-20","485:completion:22-39","485:completion:41-61","485:completion:63-75","485:completion:80-154","485:completion:156-255","485:completion:260-318","485:completion:320-362","485:completion:364-390","485:completion:392-434"},["opening"]="An egg-shaped beacon opened into a speaking mechanism. Oglethorpe's distress message placed his crashed robot at the head of the river near Skulk Rock.",["pending"]="{actor} meant to bring the beacon to the damaged robot.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fitted the beacon into the homing robot.",["sourceHash"]="cd00126bf46e83da5fcd3775d85dedb3f6c633ee0f9245444b5d10c6c4a30882",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[486]={["atomIDs"]={"486:description:1-54","486:description:56-110","486:description:115-176","486:description:178-276","486:description:279-316","486:description:321-449","486:description:452-506","486:objective:1-68"},["opening"]="Athridas prepared the Relics of Wakening for a ritual to save the Druids of the Talon. He said Ursal's interference had to end before it could work, sending the confrontation southwest to Gnarlpine Hold.",["pending"]="{actor} would confront Ursal the Mauler and return to Athridas.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against Ursal the Mauler and returned to Athridas Bearmantle.",["sourceHash"]="1c681faecd7a5f629a2c2cc7d910cc2a98efcd62f4cefb1c5b36f2287ba011c2",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[487]={["atomIDs"]={"487:description:1-40","487:description:43-171","487:description:176-259","487:description:262-330","487:description:335-384","487:description:387-436","487:description:439-496","487:objective:1-88"},["opening"]="The road between Dolanaar and Darnassus carried both commerce and important news. Reports of Gnarlpine ambushes threatened that passage, and Amara called for action against six of the attackers.",["pending"]="{actor} would undertake Amara's assignment against six Gnarlpine Ambushers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against six Gnarlpine Ambushers and returned to Amara.",["sourceHash"]="ce5e405d766bed0dad67a7911f415816dc6abb3aa0916f73a0432053a48352b5",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[488]={["atomIDs"]={"488:description:1-22","488:description:25-119","488:description:124-218","488:description:221-284","488:description:289-337","488:description:341-350","488:description:353-446","488:description:451-488","488:objective:1-121"},["opening"]="Zenn Foulhoof offered enticing promises in exchange for forest reagents. He wanted fangs, owl feathers and spider silk, and asked that the arrangement remain secret.",["pending"]="{actor} intended to gather Zenn's requested fangs, feathers and silk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered three Nightsaber Fangs, three Strigid Owl Feathers and three Webwood Spider Silks to Zenn.",["sourceHash"]="26b585f13e96c6f28f20630140abb27a37aa4d1f204ce30da8c87278c7757f5d",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[489]={["atomIDs"]={"489:description:1-64","489:description:66-101","489:description:103-190","489:description:195-291","489:description:296-345","489:description:347-401","489:description:403-431","489:description:436-457","489:description:459-508","489:objective:1-71"},["opening"]="The Council of the Forest condemned aid given to Zenn, whom Syral named an enemy of Teldrassil. The proposed remedy used smoking Fel Cones: corrupted seeds offered to the satyr as an apparently harmless snack.",["pending"]="{actor} would collect three Fel Cones and give them to Zenn.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered three Fel Cones to Zenn Foulhoof.",["sourceHash"]="9b20884085ad9aaaa522c7e528c0b791d8985f6cd96519702e7e2749e1b32032",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[491]={["aftermath"]="Bethor recognized the relic of his broken friendship and said he would have sensed its power had Thule invoked it.",["atomIDs"]={"491:description:1-140","491:description:143-287","491:description:290-337","491:description:342-346","491:description:349-421","491:description:424-448","491:objective:1-77"},["endingAtomIDs"]={"491:completion:1-16","491:completion:18-42","491:completion:44-126","491:completion:131-203","491:completion:205-244","491:completion:249-273","491:completion:275-322"},["opening"]="Alaric recounted how three apprentices had woven their wands into a token of friendship. Thule later hid the shared relic in Fenris Keep.",["pending"]="{actor} planned to carry the relic back to Bethor.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Woven Wand to Bethor.",["sourceHash"]="adbdd8d8291119316a5e7b848b0c4c8e81b02e81f0c248710c424e2297b25a4a",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[493]={["atomIDs"]={"493:description:1-98","493:description:101-154","493:description:157-263","493:description:268-408","493:description:411-441","493:description:446-479","493:description:482-506","493:objective:1-114"},["opening"]="Renferrel believed sharing research would hasten the Society's work. His latest findings needed to reach Lydon in distant Tarren Mill.",["pending"]="{actor} meant to carry the findings to Hillsbrad.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the findings to Lydon.",["sourceHash"]="e63a809e2f7936b090c1979b451d71498ee80b92f642b9ea7391a22333510a7c",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[494]={["aftermath"]="Darthalia interpreted the message as the signal that Hillsbrad was ready for attack.",["atomIDs"]={"494:description:1-32","494:description:37-105","494:description:108-143","494:description:146-231","494:description:234-300","494:description:305-348","494:description:353-417","494:description:420-430","494:description:433-488","494:objective:1-88"},["endingAtomIDs"]={"494:completion:1-42","494:completion:47-58","494:completion:60-88","494:completion:90-134","494:completion:136-163"},["opening"]="Lesh watched Hillsbrad on reconnaissance and demanded an urgent delivery. His coded message was meant for Darthalia in Tarren Mill.",["pending"]="{actor} intended to relay Lesh's coded message.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Lesh's coded message.",["sourceHash"]="aa31a65bd1c3af92980751cd01daf398fc1312e2f8c9c8af51bda31d2f270c60",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[495]={["atomIDs"]={"495:description:1-98","495:description:100-172","495:description:174-228","495:description:233-297","495:description:299-392","495:description:397-506","495:objective:1-61"},["opening"]="Mug'Thol's mission to fetch a crown for Sylvanas ended with him wearing it. Sharlindra said its power broke his imposed obedience, and sent the response toward Melisara in Tarren Mill.",["pending"]="{actor} planned to report to Melisara.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Sharlindra's lieutenant.",["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[496]={["atomIDs"]={"496:description:1-40","496:description:43-96","496:description:101-153","496:description:156-287","496:description:292-436","496:description:439-502","496:objective:1-82"},["opening"]="Lydon lacked time to collect the killing agents his experiments required. Nearby bears and creepers could supply tongues and rare ichor for the preparations.",["pending"]="{actor} planned to gather Lydon's requested specimens.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Lydon with the requested specimens.",["sourceHash"]="fddfe9214c0df5071e0611d3b8d50b3b4f17cc21f0636947afc173854fe7db94",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[498]={["aftermath"]="Krusk learned that their leader Gol'dir was taken elsewhere; his location remained unknown.",["atomIDs"]={"498:description:1-134","498:description:139-244","498:description:246-313","498:description:315-370","498:description:375-428","498:description:430-498","498:objective:1-78"},["endingAtomIDs"]={"498:completion:1-65","498:completion:67-82","498:completion:87-162","498:completion:164-195","498:completion:197-240","498:completion:245-296"},["opening"]="Krusk escaped a Syndicate ambush at Durnholde, but Drull and Tog'thar remained captive. The Warchief's expedition had become a rescue effort.",["pending"]="{actor} planned to free Krusk's captured companions.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the rescue of Drull and Tog'thar.",["sourceHash"]="2811d557acd056545ecc6d3cfc8ede8fe612b64533fe4b83c18fe1df8e2d9f24",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[499]={["atomIDs"]={"499:description:1-104","499:description:109-120","499:description:123-234","499:description:239-302","499:description:307-405","499:objective:1-34"},["opening"]="Lydon had mixed the gathered ingredients into a new poison. His assistant Umpi was the intended subject of its first test.",["pending"]="{actor} planned to administer Lydon's elixir to Umpi.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} gave Umpi the prepared elixir.",["sourceHash"]="a06d9d769ac8fe61d87a85c83965d5552df29a671175f81dabe92ebc3ad72452",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[500]={["aftermath"]="Redpath considered the pressure useful for keeping the ogres away, at least for a while.",["atomIDs"]={"500:description:1-100","500:description:103-163","500:description:168-353","500:description:358-406","500:description:409-483","500:objective:1-75","500:objective:78-121"},["endingAtomIDs"]={"500:completion:1-95","500:completion:100-137","500:completion:139-160"},["opening"]="Redpath's scouts found Crushridge ogres established not only in a mountain mound but in Alterac's ruins. He feared a secure foothold would encourage them down toward Southshore, and offered a bounty before that advance began.",["pending"]="{actor} planned to gather nine dirty knucklebones.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the knucklebones to Redpath.",["sourceHash"]="0d5a158e54e056d7a2cd8aee0ec671fc2058c6fae182113d3f3a82e24ddc4863",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[501]={["atomIDs"]={"501:description:11-83","501:description:86-136","501:description:139-246","501:description:251-331","501:description:334-352","501:description:355-460","501:description:463-507","501:objective:1-73"},["opening"]="Lydon believed mountain lion blood might form another lethal brew. His research toward the Dark Lady's plague sent the search into Hillsbrad's wildlife.",["pending"]="{actor} planned to collect ten vials of lion blood.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Lydon with the mountain lion blood.",["sourceHash"]="4c0d26d21ef12839eee306eb579fcf169e60e9a9a4e34927726d48758cfa5954",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[502]={["atomIDs"]={"502:description:1-59","502:description:64-144","502:description:147-216","502:description:219-330","502:description:333-359","502:description:364-442","502:description:445-509","502:objective:1-35"},["opening"]="Lydon had turned the lion blood into an experimental mixture. He selected Farmer Ray's dog Stanley as the test subject at the northern farm.",["pending"]="{actor} planned to give Stanley the experimental mixture.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} administered the mixture to Stanley.",["sourceHash"]="ba457adf2c04c7c989cbc2ae0ad458864b6cbf884b85aa3b97c3c4c696e985c7",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[503]={["aftermath"]="Gol'dir described forced labor in captivity and said important information had to reach the expedition's current leader.",["atomIDs"]={"503:description:1-151","503:description:153-208","503:objective:1-49"},["endingAtomIDs"]={"503:completion:1-14","503:completion:16-127","503:completion:129-220","503:completion:225-269","503:completion:271-355"},["opening"]="Documents pointed Krusk toward a northern Syndicate base, probably in Alterac. Gol'dir had remained captive while the expedition searched for him.",["pending"]="{actor} planned to find and free Gol'dir.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached and freed Gol'dir.",["sourceHash"]="f3a6b4cc94fd3fda4f9e3a06d85adb29f1ed8271c322e0c496c24b9c08fc9b5c",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[504]={["atomIDs"]={"504:description:1-95","504:description:100-167","504:description:170-307","504:objective:1-76"},["opening"]="Redpath moved the effort from the mountain's ogres to the warmongers occupying the city. His purpose remained the defense of Alliance territory through pressure on a nearby stronghold.",["pending"]="{actor} meant to confront ten warmongers in the ruins.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Redpath's warmonger assignment.",["sourceHash"]="497506e88fad365cbd2fc0599df66956079844d431995760a1466d0a2bd204a6",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[505]={["aftermath"]="Maleb hoped the dead included the assassins, while acknowledging that he did not know whether they did.",["atomIDs"]={"505:description:1-108","505:description:111-310","505:description:315-427","505:description:430-480","505:objective:1-104"},["endingAtomIDs"]={"505:completion:1-14","505:completion:16-161","505:completion:163-256","505:completion:261-299"},["opening"]="Maleb's appointment followed his predecessor's assassination. Investigators strongly suspected Syndicate employers without identifying the killers, and the new magistrate directed action against two foothill camps.",["pending"]="{actor} intended to confront the footpads and thieves.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of Maleb's camp assignment.",["sourceHash"]="3f537b7573bf9ec5510700d6705c92fb560ca204ab110e90ff0b468372a43e14",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[506]={["aftermath"]="Krusk joined the recovery of the pendant to his determination to resist renewed enslavement.",["atomIDs"]={"506:description:1-64","506:description:66-133","506:description:135-285","506:description:290-367","506:description:369-421","506:description:426-495","506:objective:1-67"},["endingAtomIDs"]={"506:completion:1-38","506:completion:40-102","506:completion:107-195","506:completion:197-271"},["opening"]="Gol'dir recounted Aliden Perenolde's plans to enslave opposing orcs. He also reported seeing the Warchief's sought pendant around Elysa's neck.",["pending"]="{actor} meant to carry Gol'dir's information to Krusk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} relayed Gol'dir's account to Krusk.",["sourceHash"]="39e672ae61ceb220eeeb796e202c2fda501957da2b8901a5fd0f79cd9a579671",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[507]={["aftermath"]="Elysa pleaded for safety and said Perenolde held her against her will.",["atomIDs"]={"507:description:1-79","507:description:81-156","507:description:158-244","507:objective:1-80"},["endingAtomIDs"]={"507:completion:1-28","507:completion:30-93","507:completion:95-103","507:completion:105-113"},["opening"]="Krusk ordered action against Perenolde at his lakeside manor. Recovering the pendant required finding Elysa as well as confronting the Syndicate lord.",["pending"]="{actor} planned to confront Perenolde and question Elysa.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the confrontation and reached Elysa.",["sourceHash"]="60b7d1f63fff2a0de19e111f3748f38e4e0e878243d7ffab9cd56021e18c0107",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[508]={["aftermath"]="Krusk admitted he did not understand the pendant's importance to the Warchief, but recognized the mission's success.",["atomIDs"]={"508:description:1-12","508:description:14-41","508:description:43-50","508:description:52-77","508:description:79-115","508:objective:1-49"},["endingAtomIDs"]={"508:completion:1-77","508:completion:79-157","508:completion:159-235"},["opening"]="Elysa relinquished the pendant and asked to be left in peace. The small object could now be carried back to Krusk.",["pending"]="{actor} meant to return Taretha's pendant to Krusk.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Taretha's pendant to Krusk.",["sourceHash"]="153863ce03d1cbe18ae05455d5bd7a0e56e2b62f1d42446f573f910c1b0441fd",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[509]={["atomIDs"]={"509:description:1-39","509:description:41-119","509:description:122-164","509:description:169-319","509:description:324-433","509:description:435-503","509:objective:1-61"},["opening"]="Lydon's next preparation began in Nethander Stead's fields. Mudsnout blossoms were the component he wanted from the gnolls' territory.",["pending"]="{actor} planned to gather six Mudsnout blossoms.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the blossoms to Lydon.",["sourceHash"]="853940e629ed6d4972616dadbb93f63947720d7ceedfb00d2a5086a1f9e4b6e9",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[510]={["aftermath"]="Maleb interpreted the request alongside earlier Syndicate actions as evidence of war against the town.",["atomIDs"]={"510:description:1-54","510:description:57-159","510:description:164-353","510:objective:1-61"},["endingAtomIDs"]={"510:completion:1-28","510:completion:33-61","510:completion:63-216"},["opening"]="A supply request paired ordinary provisions with masks, oil and poison. Its urgency and reference to an imminent mission against Southshore gave the papers significance beyond another thieves' inventory.",["pending"]="{actor} planned to bring the documents to Maleb.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the plans to Southshore.",["sourceHash"]="cb45b0cdfdd3cacccbc4d4ff3b39c8ab8716aab3bdd395552c858645bdaadd06",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[511]={["aftermath"]="Dibbs did not recognize the encryption and admitted the limits of his knowledge.",["atomIDs"]={"511:description:1-62","511:objective:1-61"},["endingAtomIDs"]={"511:completion:1-13","511:completion:15-30","511:completion:32-57","511:completion:69-194"},["opening"]="One letter on the table resisted ordinary reading. The cipher left its meaning concealed, making Dibbs's learning the first resource for discovering what it held.",["pending"]="{actor} meant to show the encrypted letter to Dibbs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the letter to the loremaster.",["sourceHash"]="454874967be69c893966736712b3c7aded3c1181f3968feb463febe518af9c09",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[512]={["aftermath"]="Maleb expected the loss of noble leadership to reduce the Syndicate's ability to act decisively.",["atomIDs"]={"512:description:1-72","512:description:75-143","512:description:148-216","512:description:219-277","512:description:282-345","512:description:348-460","512:description:465-492","512:objective:1-63"},["endingAtomIDs"]={"512:completion:1-134","512:completion:139-171"},["opening"]="Maleb feared that former Alterac nobles directed the danger to Southshore. He suspected a headquarters in Strahnbrad, but expected leaders to disguise themselves among ordinary agents; signet rings would distinguish them.",["pending"]="{actor} intended to recover seven noble signet rings.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the rings to Maleb.",["sourceHash"]="0420bb96479272bd6f93fe13e2253628188a85b831f9783b9e1b1d37c7b47903",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[513]={["atomIDs"]={"513:description:1-118","513:description:123-171","513:description:174-318","513:description:323-403","513:objective:1-75"},["opening"]="Lydon had reduced the blossoms to a composite. Faranell's colloid of decay was the next addition needed for the apothecaries' experiment.",["pending"]="{actor} meant to take the composite to Faranell.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the composite in the Undercity.",["sourceHash"]="68a4d35365d2ec3c2962a0a5ed2af4ecfb729efd09f50b2c7c95eb9080b5cb3e",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[514]={["atomIDs"]={"514:description:1-76","514:description:79-170","514:description:173-216","514:description:219-289","514:objective:1-72"},["opening"]="Dibbs turned the unread letter toward an Ironforge colleague. Stormpike's reputation for decryption offered a way beyond the loremaster's own limit.",["pending"]="{actor} planned to take the letter to Stormpike.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered it at the Explorers' library.",["sourceHash"]="aa478746d6fa95df37706a0782d6d5e649bbf113d994121295bc376e7571e99c",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[515]={["atomIDs"]={"515:description:1-21","515:description:24-44","515:description:47-73","515:description:78-137","515:description:142-357","515:description:360-423","515:description:426-482","515:objective:1-135"},["opening"]="Faranell had added his colloid, but activating the mixture required further reagents. Lydon would need a potion and materials from Hillsbrad's coastal creatures.",["pending"]="{actor} meant to bring the mixture and activating reagents to Lydon.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Lydon with the mixture and requested reagents.",["sourceHash"]="7119e748b112968127c7715bd16565aa1ba49852ac0b6d857e98932247ce1e81",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[516]={["atomIDs"]={"516:description:1-97","516:description:99-210","516:description:215-263","516:description:265-332","516:description:334-439","516:description:444-472","516:description:474-502","516:objective:1-135"},["opening"]="Allister's information about an undead gathering was uncertain. Reports placed it in a cave near Dalaran wizards, preparing an attack against the Forsaken.",["pending"]="{actor} planned to locate Beren's Peril and disrupt its force.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Allister's assignment against the Ravenclaw undead.",["sourceHash"]="9cd4c3ab18d26fe7d9b3ce62b39f9430ab72845444570a9ec281990e45066c0b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[517]={["atomIDs"]={"517:description:1-46","517:description:49-137","517:description:140-196","517:description:201-223","517:description:226-295","517:description:298-338","517:description:341-402","517:objective:1-67"},["opening"]="Lydon considered the contagious mixture ready for testing. A stolen keg from Dun Garok would provide the vessel for his next experiment.",["pending"]="{actor} planned to recover a keg of Shindigger Stout.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the keg to Lydon.",["sourceHash"]="bd325734c6b4cc6e0bee5d989538931266362255391bb95a8a2ff0029b09de43",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[518]={["atomIDs"]={"518:description:1-68","518:description:70-168","518:description:173-211","518:description:216-226","518:description:228-232","518:description:234-240","518:objective:1-55"},["opening"]="Mug'Thol's Crushridge ogres occupied Alterac's ruins. Melisara planned to reduce their strength before striking directly at their leader.",["pending"]="{actor} planned to confront ten Crushridge Maulers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Melisara's assignment against the maulers.",["sourceHash"]="1234e6ccb8217784697cd3d83d2d4197eb7a19d5ee7c3e681500e13360ca5481",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[519]={["atomIDs"]={"519:description:1-55","519:description:57-129","519:description:134-233","519:objective:1-82"},["opening"]="Melisara now turned toward Mug'Thol's lieutenants: Targ, Muckrake and Glommus. Their removal was intended to isolate the ogre leader.",["pending"]="{actor} meant to bring back the three lieutenants' heads.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the heads to Melisara.",["sourceHash"]="981f7e99e5b3f91fc38040921fc7c2b7c90eccab92612c23e010121fc4443d36",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[520]={["aftermath"]="Melisara planned to display Mug'Thol's head above Alterac and send Deathguards against the remaining Crushridge.",["atomIDs"]={"520:description:1-102","520:description:104-154","520:description:156-199","520:description:201-212","520:description:214-228","520:description:233-288","520:description:290-333","520:objective:1-85"},["endingAtomIDs"]={"520:completion:1-33","520:completion:35-181"},["opening"]="Melisara considered Mug'Thol exposed after the loss of his lieutenants. She demanded both his head and the crown he possessed.",["pending"]="{actor} planned to recover Mug'Thol's head and crown.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned both trophies to Melisara.",["sourceHash"]="d6fa67a4fa1b6171de17d7f2b09dff141dd97b7d37972b693f2b67e0df069dd7",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[521]={["aftermath"]="Sharlindra identified it as the relic used to evade Sylvanas's will and undertook its onward delivery.",["atomIDs"]={"521:description:1-80","521:description:82-132","521:description:134-250","521:objective:1-57"},["endingAtomIDs"]={"521:completion:1-71","521:completion:76-137","521:completion:139-180","521:completion:182-285"},["opening"]="The recovered crown had to reach Sharlindra for delivery to Sylvanas. Melisara warned against treating its power as a personal opportunity.",["pending"]="{actor} meant to take the crown to Sharlindra.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the crown in the Undercity.",["sourceHash"]="f3ca8476ca4ef12f1ef58c7748863c93be05b040611278eefab77d3cf1d48731",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[522]={["aftermath"]="Maleb took it as the explanation for Southshore's latest attack and a repetition of the danger that killed his predecessor.",["atomIDs"]={"522:description:1-67","522:description:70-139","522:objective:1-64"},["endingAtomIDs"]={"522:completion:1-30","522:completion:35-80","522:completion:82-151"},["opening"]="A sealed contract named Maleb as the intended victim of an assassination. Its red-wax stamp preserved the distinctive impression of the signet used to authorize it.",["pending"]="{actor} meant to warn Maleb with the contract.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} placed the contract before its intended victim.",["sourceHash"]="41a355aad334e3478846b672d1aedc24a137634dc6417d409b50990df225ab9a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[523]={["aftermath"]="Maleb expressed relief that the man behind the contract was dead.",["atomIDs"]={"523:description:1-149","523:description:152-208","523:description:213-226","523:description:229-263","523:description:266-384","523:objective:1-65"},["endingAtomIDs"]={"523:completion:1-14","523:completion:16-76"},["opening"]="Maleb identified Vardus as the contract's signer. The former Alterac noble might be among Strahnbrad's ruins or in the valley beyond, leaving the search broader than a single fixed camp.",["pending"]="{actor} intended to bring Vardus's head to Maleb.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the baron's head.",["sourceHash"]="de80263f957ff4bf3f8b53aa55069239197dfdac360a024674d711a6987d73ad",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[524]={["atomIDs"]={"524:description:1-69","524:description:72-182","524:description:185-258","524:description:261-349","524:description:354-402","524:description:405-433","524:description:438-485","524:description:488-508","524:objective:1-58"},["opening"]="Darthalia had placed captured farmers at Lydon's disposal. His tainted keg was to be set among them as the final preparation for his test.",["pending"]="{actor} planned to place the tainted keg in the prisoners' room.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} set the tainted keg on the rug.",["sourceHash"]="64e93d8c61448745b39e78be36de34b00f5765502273217ec6e79fc241025f43",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[525]={["aftermath"]="Maleb judged the author neither a thief nor an Alterac noble and feared another power behind the Syndicate.",["atomIDs"]={"525:description:1-60","525:description:63-116","525:description:119-133","525:description:138-190","525:description:193-305","525:objective:1-61"},["endingAtomIDs"]={"525:completion:1-25","525:completion:30-98","525:completion:100-159","525:completion:164-257"},["opening"]="Stormpike had removed the cipher but not the letter's deeper mystery. Its discovery among Alterac thieves made Southshore's magistrate the next reader of a possible local threat.",["pending"]="{actor} planned to carry the deciphered letter to Maleb.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Stormpike's translation.",["sourceHash"]="d18682a0ae3e0349da26c87dd75e5be8518757829a3b7a85a66342a21f017c9a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[526]={["atomIDs"]={"526:description:1-104","526:description:109-151","526:description:154-227","526:objective:1-76"},["opening"]="Glorin could not fashion useful work from one Lightforge Ingot. He suspected the murlocs around the wreck held more and called for five ingots before the metal could serve its intended purpose.",["pending"]="{actor} intended to gather five Lightforge Ingots and return to Glorin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Glorin Steelbrow with the five requested Lightforge Ingots.",["sourceHash"]="4becabae5f450a2ebb3a03439cb570218e08a48c1a425da9812073afd81d38ff",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[527]={["atomIDs"]={"527:description:1-43","527:description:48-88","527:description:91-178","527:description:183-269","527:description:272-353","527:description:358-369","527:description:372-419","527:description:422-501","527:objective:1-120"},["opening"]="Darthalia's first strike targeted Hillsbrad's food supply. Under Varimathras's command, she ordered an attack on the northern farms and their landowners.",["pending"]="{actor} meant to carry out Darthalia's northern farm assault.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of the northern farm assignment.",["sourceHash"]="c9478aaa113dfaf3191895a3d55a9164fa44eec36aa15dc290542a02d5801490",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[528]={["atomIDs"]={"528:description:1-68","528:description:71-85","528:description:90-167","528:description:170-237","528:description:242-262","528:description:265-326","528:description:329-375","528:description:380-389","528:objective:1-71"},["opening"]="Deathstalkers reported peasants fleeing toward the southern orchards. Darthalia followed the farm attack with orders to pursue those seeking cover.",["pending"]="{actor} meant to carry out Darthalia's pursuit in the fields.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of the peasant assignment.",["sourceHash"]="f0583559d8d70442c59ee12b363097da4d1f0c023f486d3a372270c01433513a",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[529]={["atomIDs"]={"529:description:1-67","529:description:70-154","529:description:157-194","529:description:199-252","529:description:255-283","529:description:286-349","529:description:352-461","529:objective:1-66","529:objective:71-142"},["opening"]="Hillsbrad's resistance was being armed by its blacksmith. Darthalia targeted Verringtan's workshop and its iron stockpile to cut that supply.",["pending"]="{actor} planned to strike the workshop and recover its iron.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the workshop assignment and returned the iron.",["sourceHash"]="4db24711abc2b284576924fd3f83308cc2c681380317c9c2a6f48aeabbe97fcc",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[530]={["aftermath"]="Raleigh kept the hands as a remembrance of betrayal and relinquished Deliah's ring.",["atomIDs"]={"530:description:1-53","530:description:56-115","530:description:118-191","530:description:196-303","530:objective:1-19","530:objective:24-75"},["endingAtomIDs"]={"530:completion:1-9","530:completion:11-45","530:completion:47-131","530:completion:136-176","530:completion:178-263","530:completion:265-338"},["opening"]="Raleigh identified his former friend Valdred as Deliah's murderer. He sought revenge at the Greymane Wall, where Valdred was last reported fleeing.",["pending"]="{actor} meant to bring Valdred's hands to Raleigh.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Valdred's hands to Raleigh.",["sourceHash"]="f6d8915a92bf7c6908933d54f3820497430ed2c09981b66e6e59fadc686ffa21",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[531]={["atomIDs"]={"531:description:1-6","531:description:8-53","531:description:55-89","531:description:97-107","531:description:112-145","531:description:147-200","531:objective:1-66"},["opening"]="Daryl wanted the bloody trophy out of the lodge. Ol' Sooty's head had another destination there: Vyrin Swiftwind, who proposed this answer to the hunter's pride.",["pending"]="{actor} planned to take Ol' Sooty's head to Vyrin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Ol' Sooty's head to Vyrin Swiftwind.",["sourceHash"]="03ecb7aa57cd6f67b2dfa2ebbc87c7a4af891257020784fca474c8582d92322f",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[532]={["atomIDs"]={"532:description:1-70","532:description:73-181","532:description:186-279","532:description:282-362","532:description:365-441","532:description:444-491","532:objective:1-52","532:objective:55-89","532:objective:92-125","532:objective:128-178"},["opening"]="Despite its losses, Hillsbrad continued to rally around its leaders. Darthalia ordered an attack on the council, its proclamation and the town's records.",["pending"]="{actor} meant to carry out the council and registry assignment.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled Darthalia's orders against Hillsbrad's leadership.",["sourceHash"]="afd591b1cbfc076a37a097eda70b0dca6d4a98dd56b8e4fd04272c3fee101f2e",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[533]={["aftermath"]="Krusk regarded the recovered evidence as establishing where Gol'dir was held.",["atomIDs"]={"533:description:1-80","533:description:82-218","533:description:223-298","533:objective:1-74"},["endingAtomIDs"]={"533:completion:1-45","533:completion:47-191"},["opening"]="Rumors and evidence had narrowed Krusk's search for Gol'dir. A Syndicate camp to the north might hold documents that could establish his whereabouts.",["pending"]="{actor} planned to recover information from the northern camp.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned information about Gol'dir's captivity.",["sourceHash"]="29ce08787210d10fc888bbf8133feba517866917e5dd2aab88a8461706bbf67c",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[535]={["aftermath"]="Valik savored the drink and handed over something he thought would no longer serve him.",["atomIDs"]={"535:description:1-8","535:description:10-57","535:description:62-207","535:objective:1-63"},["endingAtomIDs"]={"535:completion:1-98","535:completion:100-151","535:completion:156-176"},["opening"]="Valik was injured and expected to die in an enemy's presence. He offered information for a mug of Southshore stout, seeking one comfort before the end he anticipated.",["pending"]="{actor} meant to bring Valik the stout.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered a mug to Valik.",["sourceHash"]="c15b504ed9ca7989298ddcbd815ac7978879b388dac2ca8600c096e7c43cd0b3",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[536]={["atomIDs"]={"536:description:1-110","536:description:112-145","536:description:150-178","536:description:180-216","536:description:226-330","536:description:332-400","536:objective:1-98"},["opening"]="Farren resented his posting to Southshore and Redpath's orders about the coast. He sought help against the Torn Fin murlocs on the Western Strand.",["pending"]="{actor} planned to confront the strand's tidehunters and oracles.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Farren's assignment against the Torn Fin.",["sourceHash"]="02b2af555f5ea0ab988e95d8533a08fd46e9c35f7c9f0c6b368153ee3c80b6de",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[537]={["aftermath"]="Maleb warned that Nagaz served another power and that the Argus Wake might extend far beyond Alterac.",["atomIDs"]={"537:description:1-101","537:description:104-214","537:description:219-295","537:description:298-336","537:description:341-396","537:description:399-424","537:description:429-488","537:objective:1-26","537:objective:31-88"},["endingAtomIDs"]={"537:completion:1-14","537:completion:16-88","537:completion:93-187","537:completion:189-251","537:completion:256-273"},["opening"]="The letter named Nagaz and the Argus Wake, but Maleb did not know the organization. Its apparent alliance with the Syndicate led him to target its envoys in the Uplands.",["pending"]="{actor} intended to confront Nagaz and four shadow mages.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Nagaz's head after completing the assignment.",["sourceHash"]="f12f4e1f058054dd524fb733d8809b710d0b1fcec90314aa482348769f5d2222",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[538]={["atomIDs"]={"538:description:6-107","538:description:112-203","538:description:206-297","538:description:300-327","538:description:332-386","538:description:389-429","538:description:432-500","538:objective:1-42"},["opening"]="Alterac's ruined libraries represented lost knowledge as well as a fallen kingdom. Milton wanted books saved for Stormwind, beginning with Dibbs in Southshore, the nearest town to the remains.",["pending"]="{actor} planned to consult Loremaster Dibbs in Southshore.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Loremaster Dibbs.",["sourceClassMask"]="?",["sourceHash"]="068b1ed81db4460b848bfc07a61627f081216811ec7081bd7fdc2cf575bdb728",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[539]={["atomIDs"]={"539:description:1-88","539:description:91-168","539:description:173-309","539:description:314-350","539:description:353-412","539:description:415-438","539:description:441-489","539:objective:1-87"},["opening"]="Hillsbrad's registry identified Azureload Mine as a source of iron for Alliance armories. Darthalia directed the campaign south toward Bonds and his miners.",["pending"]="{actor} meant to carry out the Azureload Mine assignment.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of the mine assault.",["sourceHash"]="fcdc77db9b40ad007ebf807befb378ae80c4c833e8e145219042fd81e15966fd",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[540]={["aftermath"]="Dibbs began studying the recovered Gri'lek text. Its preservation made further reading possible after the ruin that nearly lost it.",["atomIDs"]={"540:description:1-133","540:description:136-165","540:description:170-237","540:description:240-348","540:description:351-484","540:objective:1-114"},["endingAtomIDs"]={"540:completion:1-17","540:completion:19-27","540:completion:29-81"},["opening"]="Ogres occupied Alterac's ruins while precious books remained there. Dibbs sought five rescued tomes and, especially, the surviving copy of a text on Gri'lek's troll lore.",["pending"]="{actor} meant to recover five tomes and the Worn Leather Book for Dibbs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered five Recovered Tomes and the Worn Leather Book to Loremaster Dibbs.",["sourceClassMask"]="?",["sourceHash"]="946c2d728f425a6deef1259f4e99f70fd4fa9bcca379f1bda3f7eb747e70c084",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[541]={["atomIDs"]={"541:description:1-26","541:description:29-60","541:description:65-117","541:description:120-216","541:description:219-278","541:description:283-380","541:description:383-448","541:description:451-491","541:objective:1-132"},["opening"]="Darthalia turned against the dwarven force aiding Hillsbrad. Dun Garok's barracks and Captain Ironhill became the final military target of her campaign.",["pending"]="{actor} meant to carry out the Dun Garok assault.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled Darthalia's orders at Dun Garok.",["sourceHash"]="4f9229e5b1ca6bb9e16a3b5b1a613dda743aefb7f5e148c3d4a1771bf1318184",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[542]={["aftermath"]="Milton saw the surviving books as preserved human knowledge and an addition to the Royal Library. Alterac's destruction had not erased every part of its learning.",["atomIDs"]={"542:description:1-168","542:description:173-253","542:description:256-330","542:objective:1-56"},["endingAtomIDs"]={"542:completion:11-24","542:completion:26-80","542:completion:82-105","542:completion:110-123","542:completion:125-142","542:completion:144-247"},["opening"]="Dibbs kept the Gri'lek text for study and packed the other rescued books for Stormwind. Their catalogued return could restore part of Alterac's scattered learning to a working library.",["pending"]="{actor} intended to bring the Tomes of Alterac to Milton.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Tomes of Alterac to Milton Sheaf.",["sourceClassMask"]="?",["sourceHash"]="2e87f5815860ac8abf9ee62c2f25e6cd4826eca9046d73b652eaf8943f56f9d4",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[543]={["atomIDs"]={"543:description:1-129","543:description:132-235","543:description:240-429","543:description:434-476","543:objective:1-62"},["opening"]="Rumor placed the lost Perenolde heirloom with Grel'borg, an ogre mage searching Alterac's ruins. Ridgewell wanted the emerald tiara recovered from the treasury of a fallen ruling family.",["pending"]="{actor} planned to recover the Perenolde Tiara for Ridgewell.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Perenolde Tiara to Count Remington Ridgewell.",["sourceClassMask"]="?",["sourceHash"]="b412cd89ed40eecd103cd7befcdbb7186fb854d26aa48ac8fc57d73745a30e69",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[544]={["atomIDs"]={"544:description:1-65","544:description:68-126","544:description:129-220","544:description:225-341","544:description:344-388","544:description:393-503","544:objective:1-93"},["opening"]="Voidglare reported that four Forsaken stole research artifacts before fleeing the Undercity. Dalaran's wizards held them in the Lordamere camp.",["pending"]="{actor} planned to recover the four stolen artifacts.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the artifacts to Voidglare.",["sourceHash"]="8828acb59e0e39cb4074505175a777b812830fd5882a107ba0a7689f34da2e33",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[545]={["aftermath"]="Voidglare considered the ruins searchable with care, rather than free of danger.",["atomIDs"]={"545:description:1-87","545:description:90-222","545:description:227-259","545:description:262-366","545:description:371-438","545:description:443-511","545:objective:1-96"},["endingAtomIDs"]={"545:completion:1-10","545:completion:12-78","545:completion:83-96"},["opening"]="The ruins outside Dalaran's dome might conceal magical treasures. Voidglare wanted their wizard and elemental patrols reduced before anyone searched them.",["pending"]="{actor} planned to confront the summoners and their elementals.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Voidglare's patrol assignment.",["sourceHash"]="b36514c69b9c95b218c37386509930cfe34fce291423623b248770c796414079",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[546]={["atomIDs"]={"546:description:1-77","546:description:80-95","546:description:104-255","546:description:260-317","546:description:320-356","546:description:359-410","546:description:413-504","546:objective:1-64"},["opening"]="Samsa remained on guard while Darthalia's recruits fought in Hillsbrad. His personal collection created another demand alongside the campaign: thirty human skulls.",["pending"]="{actor} planned to gather the skulls Samsa requests.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered thirty Hillsbrad skulls to Samsa.",["sourceHash"]="0f7a9b9ec9fe330a9af7e5cc1d63531473efc60d572cb9c7a7bddbbeb51179b8",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[547]={["atomIDs"]={"547:description:1-75","547:description:78-113","547:description:116-188","547:description:193-250","547:description:255-335","547:description:338-353","547:description:356-408","547:description:411-505","547:objective:1-87"},["opening"]="Humbert said dwarven scouts took his gear while he gathered firewood near Dun Garok. Among the missing possessions, his sword mattered most.",["pending"]="{actor} planned to recover Humbert's missing sword.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the sword to Humbert.",["sourceHash"]="3aaa31d240173991b1866e42b5e273be1d81fb2085d2f675dfabacd8dfde0e36",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[549]={["atomIDs"]={"549:description:1-106","549:description:108-179","549:description:181-284","549:description:289-382","549:objective:1-51","549:objective:53-117"},["opening"]="A Forsaken notice condemned Syndicate members gathering at Durnholde. Darthalia offered payment for proof of action against its rogues and watchmen.",["pending"]="{actor} planned to fulfill the Durnholde bounty.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of the Syndicate assignment.",["sourceHash"]="4f1b50b5f5726546fee5e1c8852ee65412fa6438077bcb6d9ad5d3f804312764",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[550]={["atomIDs"]={"550:description:1-181","550:description:186-247","550:description:250-267","550:objective:1-69"},["opening"]="Darthalia had prepared a sealed commendation for the Undercity. Her account of the Hillsbrad fighting was intended for Varimathras's attention.",["pending"]="{actor} meant to carry the commendation to Varimathras.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Darthalia's sealed commendation.",["sourceHash"]="7ede559aa27769a88312e8670552105b7b0ecc4594324dd8b7197450e4232344",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[551]={["aftermath"]="Dibbs again admitted that the writing exceeded his ability to decipher it.",["atomIDs"]={"551:description:1-70","551:description:73-121","551:description:128-138","551:objective:1-65"},["endingAtomIDs"]={"551:completion:1-21","551:completion:26-124","551:completion:126-161"},["opening"]="Magic rendered the parchment unreadable except for one name at its head. That surviving word connected the text to Nagaz, but left its purpose concealed.",["pending"]="{actor} planned to take the parchment to Dibbs.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the enchanted parchment.",["sourceHash"]="d1670fe2236aabcd45a1aba5261a0f0e2a06b4edf299b865f0ce40ef66396a9c",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[552]={["atomIDs"]={"552:description:1-159","552:description:162-233","552:description:238-289","552:description:292-388","552:description:393-426","552:description:429-458","552:description:461-497","552:objective:1-90"},["opening"]="Thaivand said a mob killed Helcular during his transformation into a lich. His revenge began with recovering the rod from the yeti-occupied ritual lair.",["pending"]="{actor} planned to recover Helcular's rod.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the rod to Thaivand.",["sourceHash"]="5d645cd68530ef9ec54fa5a75c464f977b5d76b48fb215880fd26e89141e93a9",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[553]={["aftermath"]="A great rumbling rose from the ground beneath Helcular's grave.",["atomIDs"]={"553:description:1-31","553:description:33-49","553:description:54-126","553:description:129-201","553:description:203-285","553:description:290-355","553:description:357-480","553:description:483-506","553:objective:1-102","553:objective:107-164"},["endingAtomIDs"]={"553:completion:1-42"},["opening"]="Thaivand's ritual required three flames in the caves and mountains. Their power had to charge the rod before it was planted in Helcular's Southshore grave.",["pending"]="{actor} planned to charge the rod and complete the grave ritual.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the ritual at Helcular's grave.",["sourceHash"]="1f5c6feeab9aa15e18ce29aebd8484d0aeaa60bc90a8badc8a9bcc0a66acb437",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[554]={["aftermath"]="Stormpike undertook its translation and promised to summon further help if the contents proved interesting.",["atomIDs"]={"554:description:1-63","554:description:66-148","554:description:151-226","554:description:231-333","554:objective:1-68"},["endingAtomIDs"]={"554:completion:1-16","554:completion:18-111","554:completion:113-160","554:completion:162-181"},["opening"]="Dibbs referred the enchanted parchment to Stormpike's specialized skill. The Ironforge scholar might make sense of another Alterac document the loremaster could not read.",["pending"]="{actor} meant to carry the parchment to Stormpike.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the scroll in Ironforge.",["sourceHash"]="ac1f6f3aca6751f43e0fa594391a004058497a0dbaca0a33d2c841a4f547bf2f",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[555]={["aftermath"]="Jessen announced that his turtle bisque could be served again.",["atomIDs"]={"555:description:1-113","555:description:118-170","555:description:172-244","555:description:247-304","555:description:307-411","555:description:413-511","555:objective:1-85"},["endingAtomIDs"]={"555:completion:1-87"},["opening"]="Jessen could not safely hunt the Lordamere snapjaws himself. Turtle meat and soothing spices would let the Southshore chef serve his well-known bisque again.",["pending"]="{actor} meant to bring Jessen meat and spices.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the ingredients for Jessen's bisque.",["sourceHash"]="b5b61ecffe7d5e7dec22b26f7ca36d1ba392b79c5d07317cdc9b05e7aca5d9de",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[556]={["aftermath"]="Their magic appeared faded, which Bel'varil considered suitable for the first experiments.",["atomIDs"]={"556:description:1-122","556:description:125-194","556:description:197-253","556:description:258-344","556:description:349-446","556:description:449-479","556:objective:1-62"},["endingAtomIDs"]={"556:completion:1-21","556:completion:23-156","556:completion:161-174"},["opening"]="Dalaran's wizards used tokens to control elementals. Bel'varil sought examples for Voidglare and suggested the internment camp as the less dangerous hunting ground.",["pending"]="{actor} planned to collect ten worn stone tokens.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the tokens to Bel'varil.",["sourceHash"]="4b3a23ef0742112fb10c1c58da7c844a69212cd128b86ec5f1fd49fb8d035762",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[557]={["atomIDs"]={"557:description:1-148","557:description:151-242","557:description:247-359","557:objective:1-68"},["opening"]="The tokens had a counterpart on the elementals themselves. Bel'varil wanted the earth-binding bracers that held those creatures in a mage's service.",["pending"]="{actor} planned to recover four earth-binding bracers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the bracers to Bel'varil.",["sourceHash"]="56c3f57dff3e6e7bbfaeeba9d509e48880a740751077466fd8b603da4d026bef",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[558]={["atomIDs"]={"558:description:1-105","558:description:108-161","558:description:166-187","558:description:190-221","558:description:224-258","558:description:261-337","558:description:339-346","558:description:349-386","558:description:389-428","558:description:433-439","558:objective:1-89"},["opening"]="The ward dreamed of becoming an Alliance hero like Jaina. An autograph from Theramore seemed too much for the child to request alone, but an adventuring guardian might make the introduction.",["pending"]="{actor} planned to obtain Jaina Proudmoore's autograph for the ward.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Jaina autograph errand for the ward.",["sourceClassMask"]="?",["sourceHash"]="01d16e681b202695d43053f714cb2c932f47b0ef7172ea589fdc06a3fd972111",["sourceMapID"]="?",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[559]={["atomIDs"]={"559:description:1-25","559:description:27-132","559:description:134-241","559:objective:1-108"},["opening"]="Redpath required proof of the coastal fighting. Farren's next request concerned murloc heads rather than another unsupported report.",["pending"]="{actor} planned to collect ten heads from the Western Strand.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the heads to Farren.",["sourceHash"]="cb2177ccfb8cacde0dc2bf0f21caf90dc7037459da80f6decdb5e2cffd3db0d9",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[560]={["atomIDs"]={"560:description:1-55","560:description:57-148","560:objective:1-67"},["opening"]="Farren refused to carry the gathered heads himself. The sack still had to reach Redpath before the marshal could inspect the evidence.",["pending"]="{actor} meant to deliver the sack to Redpath.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the murloc heads to Redpath.",["sourceHash"]="300e112302152c08c1d18aa762c0484f15ee5da41741e5785004104c3e77ca02",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[561]={["atomIDs"]={"561:description:1-120","561:description:122-177","561:objective:1-52"},["opening"]="Redpath redirected Farren toward the Eastern Strand's naga. He also wanted future results reported in person, making the message a personal summons.",["pending"]="{actor} meant to relay Redpath's new orders.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the orders to Farren.",["sourceHash"]="db32c1961cdc6dc9850f36348b65472ccb336f64622b4c3178debdf1ee872d96",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[562]={["aftermath"]="Farren expected the reported success to help secure a return to Stormwind.",["atomIDs"]={"562:description:1-149","562:description:151-280","562:description:285-317","562:description:319-346","562:description:348-465","562:description:467-492","562:objective:1-104"},["endingAtomIDs"]={"562:completion:1-73","562:completion:75-108","562:completion:110-148"},["opening"]="Farren's former mentor reported opportunities for soldiers who addressed the naga threat. Farren hoped for reassignment but admitted the creatures exceeded his abilities.",["pending"]="{actor} planned to help confront the Daggerspine forces.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Farren's assignment against the naga.",["sourceHash"]="eea58e3a703b11c089de76e65480d74405b41e6e3ac327b8b52e2deadaf31ae1",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[563]={["aftermath"]="Samuelson agreed to consider it during the next personnel review, without promising a transfer.",["atomIDs"]={"563:description:1-49","563:description:51-146","563:description:148-230","563:description:232-281","563:description:283-320","563:objective:1-61"},["endingAtomIDs"]={"563:completion:1-12","563:completion:20-102","563:completion:104-230"},["opening"]="Farren sent his report privately to Samuelson, his former mentor in Stormwind. He hoped its account would support a transfer away from Southshore.",["pending"]="{actor} meant to deliver Farren's report to Samuelson.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the report at Stormwind Keep.",["sourceHash"]="68be205c971e2f6f7e32d9d8ead630107e0f49cab2c22ca7dfb2bb435eb29ba2",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[564]={["atomIDs"]={"564:description:1-72","564:description:75-242","564:description:247-375","564:description:378-440","564:description:445-470","564:description:473-506","564:objective:1-93"},["opening"]="Darren's horses faced many dangers, but he blamed Alterac's mountain lions for the worst losses. He wanted the predators above Southshore reduced.",["pending"]="{actor} planned to confront the mountain lions threatening the horses.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Darren's assignment against the lions.",["sourceHash"]="8d528987607389dc55594b98b3cc46d151d41db90abdc651fc097e0b711a27c1",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[565]={["atomIDs"]={"565:description:1-93","565:description:98-160","565:description:163-195","565:description:198-243","565:description:246-271","565:description:276-395","565:description:398-455","565:objective:1-110"},["opening"]="Bartolo's boasting rested on a practical list: wool, a leatherworker's cloak, thread and yeti fur. The Southshore tailor needed them before his needle could work.",["pending"]="{actor} planned to assemble Bartolo's cloak materials.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the materials to Bartolo.",["sourceHash"]="184dcac3ce8990cad1a79e2d1acb9011c34e648a920804472c96a3e5a51d5429",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[566]={["atomIDs"]={"566:description:1-111","566:description:113-199","566:description:204-285","566:description:290-307","566:description:309-384","566:objective:1-81"},["opening"]="Darthalia's notice named Vardus as a high-ranking Syndicate member. His last reported location lay in the Uplands north of Tarren Mill.",["pending"]="{actor} planned to pursue the bounty on Vardus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Vardus's head to Darthalia.",["sourceHash"]="18e1ff76eaa8ae367c22877315f82270ae9b3d28d03f164dbd17afd17de3bf8b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[567]={["atomIDs"]={"567:description:1-10","567:description:15-128","567:description:133-157","567:description:160-200","567:description:205-219","567:description:222-261","567:description:266-279","567:description:282-323","567:description:328-341","567:description:344-396","567:description:401-457","567:description:460-511","567:objective:1-137"},["opening"]="Darthalia's bounty listed four Hillsbrad residents accused of attacks on Forsaken personnel or supplies. The notice warned that each was hiding.",["pending"]="{actor} planned to fulfill the four named bounties.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported completion of Darthalia's named-target assignment.",["sourceHash"]="250edb4aceccb1ce6329c0ce8c9102eefe6627fb5532ef286a245d456aa6024d",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[568]={["atomIDs"]={"568:description:1-13","568:description:18-60","568:description:63-191","568:description:194-301","568:description:306-390","568:description:393-468","568:objective:1-85"},["opening"]="Aggro'gosh's charge at Grom'gol was the safety of the Horde and a supply route to Stonard. Raptors outside the camp hampered that mission, prompting an assignment against fifteen Lashtails.",["pending"]="{actor} would undertake the Lashtail assignment for Grom'gol's commander.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against fifteen Lashtail Raptors and reported to Aggro'gosh.",["sourceClassMask"]="?",["sourceHash"]="bb2bb2b1d535d2eed9ac73bdcaf25826ee3158efd6d6e9a27561cf9240f11018",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[569]={["atomIDs"]={"569:description:1-87","569:description:90-146","569:description:149-178","569:description:181-261","569:description:264-325","569:description:330-398","569:description:403-462","569:description:465-510","569:objective:1-105"},["bridge"]="The raptor assignment had returned to Grom'gol's commander, but the supply route still faced deliberate attacks. Aggro'gosh sent the next effort toward ogres at Mizjah Ruins who continued ambushing caravans.",["bridgeFrom"]=568,["bridgeReplacesSetup"]=true,["opening"]="Ogres at Mizjah Ruins continued ambushing supply caravans despite Grom'gol's warnings. Aggro'gosh described the war as unwanted but treated the route to Stonard as too important to leave under attack.",["pending"]="{actor} intended to confront ten Ogre Brutes and five Ogre Witch Doctors.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Aggro'gosh's assignment against the specified ogres.",["sourceClassMask"]="?",["sourceHash"]="214ec4a20210e135300a5e55718c150d98bf36fe0f735b4e3587748393d08495",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[570]={["atomIDs"]={"570:description:1-81","570:description:84-124","570:description:127-164","570:description:167-220","570:description:225-291","570:description:294-319","570:description:322-354","570:description:359-486","570:objective:1-99"},["opening"]="Mok'thardin sought to harness jungle magic for the Horde. His proposed enchantment began with Shadowmaw claws and a tigress fang whose pristine condition mattered as much as its source.",["pending"]="{actor} meant to gather eight Shadowmaw Claws and a Pristine Tigress Fang.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered eight Shadowmaw Claws and a Pristine Tigress Fang to Mok'thardin.",["sourceClassMask"]="?",["sourceHash"]="ca96140b9ec6241de141c85df79f6495aef7feaadfb3726a7e8f3fcf887295fb",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[571]={["atomIDs"]={"571:description:1-58","571:description:63-154","571:description:157-193","571:description:198-260","571:description:263-312","571:description:317-342","571:description:345-447","571:objective:1-64"},["bridge"]="The feathers joined the fang and claws, but the pieces still needed binding. Mok'thardin required a flawless aged gorilla sinew to serve as the magical tether.",["bridgeFrom"]=572,["bridgeReplacesSetup"]=true,["opening"]="The feathers, claws and fang required a magical tether. Mok'thardin would accept only a perfect sinew from an Elder Mistvale Gorilla, the aged animals foraging east of Booty Bay.",["pending"]="{actor} intended to find an Aged Gorilla Sinew for Mok'thardin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered an Aged Gorilla Sinew to Mok'thardin.",["sourceClassMask"]="?",["sourceHash"]="9fcc05d1415f4d8036be78e48154510e6084d07ecb13635d2de8d360272e05ac",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[572]={["atomIDs"]={"572:description:1-119","572:description:122-260","572:description:265-324","572:description:327-394","572:description:397-490","572:objective:1-83"},["bridge"]="The cat trophies had supplied the first materials for Mok'thardin's work. The enchantment now required ten feathers from Jungle Stalkers south of Grom'gol, near the arena.",["bridgeFrom"]=570,["bridgeReplacesSetup"]=true,["opening"]="The cat trophies were only the beginning of Mok'thardin's enchantment. Ten feathers worn on Jungle Stalker armbands were the next requirement, found among raptors south of Grom'gol near the arena.",["pending"]="{actor} planned to obtain ten Jungle Stalker Feathers for Mok'thardin.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered ten Jungle Stalker Feathers to Mok'thardin.",["sourceClassMask"]="?",["sourceHash"]="a761171c3f3f37b6fe0bd61fd646e78a2cb93ad9d9ed522362a0f769f701ca7c",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[573]={["aftermath"]="The Holy Spring Water made the ceremonial choker ready for enchantment. Mok'thardin tied its intended use to the Warchief and the Horde's defense.",["atomIDs"]={"573:description:1-66","573:description:71-153","573:description:156-240","573:description:243-328","573:description:333-387","573:description:390-399","573:description:402-463","573:description:466-505","573:objective:1-57","573:objective:60-103"},["bridge"]="The tether had reached Mok'thardin. Holy Spring Water remained as the final reagent, drawing the errand south toward a disputed spring and the naga explorers gathered there.",["bridgeFrom"]=571,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"573:completion:1-75","573:completion:80-168"},["opening"]="Mok'thardin's last reagent was water from a holy spring above the southern western bluffs. Scholars disputed whose people the waters favored, while a naga expedition had moved upon the site.",["pending"]="{actor} would obtain Holy Spring Water and meet the assignment against ten Naga Explorers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied the Holy Spring Water and completed Mok'thardin's assignment against ten Naga Explorers.",["sourceClassMask"]="?",["sourceHash"]="9bb04429e3762a19913574c57a963f9198d6642648b85a4a41997cf5c70cc704",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[574]={["atomIDs"]={"574:description:1-89","574:description:92-249","574:description:254-342","574:description:345-386","574:description:391-463","574:description:466-500","574:objective:1-53","574:objective:58-102"},["opening"]="Yohwa turned from Kurzen's regular soldiers toward the skilled commandos and headshrinkers in the Stockpile. He knew many of these loyal, cruel troops personally and wanted Doren to hear the result firsthand.",["pending"]="{actor} would undertake the assignment against ten Kurzen Commandoes and six Headshrinkers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the specified special-forces assignment and reported to Lieutenant Doren.",["sourceClassMask"]="?",["sourceHash"]="1b351b59ba6f1196c63fa744f8d47d8c3ad666e8ed9a138e6bc55a7f6c623453",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[575]={["atomIDs"]={"575:description:1-99","575:description:105-113","575:description:115-131","575:description:133-137","575:description:139-143","575:description:148-233","575:description:238-360","575:description:362-388","575:description:393-504","575:objective:1-61"},["opening"]="A Tinkers' Union order had reached Drizzlik for a dozen pairs of Excelsior boots. Their basic shape required two large skins from the river crocolisks of northern Stranglethorn.",["pending"]="{actor} intended to bring two Large River Crocolisk Skins to Drizzlik.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered two Large River Crocolisk Skins to Drizzlik.",["sourceClassMask"]="?",["sourceHash"]="14749e0b026956358ba547cde0167eaa804e81423ce60577905d2f909abc3ca4",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[576]={["atomIDs"]={"576:description:1-6","576:description:9-23","576:description:28-83","576:description:86-146","576:description:149-272","576:description:277-356","576:description:359-380","576:description:383-435","576:description:440-486","576:objective:1-87"},["opening"]="Dizzy's enchanted glass eye had restored the sight battle took from him. Bloodsail attackers stole it during a night in port, leaving him to ask for the device that made seeing possible again.",["pending"]="{actor} meant to recover Dizzy One-Eye's enchanted eye from the Bloodsails.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned Dizzy's Eye to Dizzy One-Eye.",["sourceClassMask"]="?",["sourceHash"]="4ee650033dd8d18849896839b06ccd7985f493bff3c063beb993f4b5e91a376e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[577]={["atomIDs"]={"577:description:1-166","577:description:171-350","577:description:355-510","577:objective:1-58"},["opening"]="The boots had their basic shape, but still lacked inner layers. Drizzlik reserved finer leather for visible work and sought five thicker Snapjaw skins from Lake Nazferiti to fill the insides.",["pending"]="{actor} planned to collect five Snapjaw Crocolisk Skins for Drizzlik.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered five Snapjaw Crocolisk Skins to Drizzlik.",["sourceClassMask"]="?",["sourceHash"]="c9dbde9f2c5dde175e6911299b0377ed94f9faf0e380751bae431fec3f7e10dd",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[578]={["atomIDs"]={"578:description:1-124","578:description:129-171","578:description:173-197","578:description:199-400","578:description:405-461","578:objective:1-56"},["opening"]="The reported goblin and water elementals made Revilgaz wonder whether Gazban had found the Stone of the Tides. He wanted the haunted island located before the rumor became more than a possible opportunity.",["pending"]="{actor} planned to locate the haunted island for Revilgaz.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the haunted-island scouting assignment and reported to Revilgaz.",["sourceClassMask"]="?",["sourceHash"]="59f1e111d85e07f2ccb0228580db72e7e17198c0c58141f4405839a1922e5b44",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[579]={["atomIDs"]={"579:requestItems:1-153","579:requestItems:155-171","579:requestItems:173-258"},["coverageQualification"]="BASIC_RETAINED_EXCHANGE_CONTEXT",["minimumStage"]=3,["objectiveSummary"]="Bring a library scrip to Donyal Tovald for a copy of an available book.",["opening"]="Royal funding allowed the library to offer copies of its books to the public. Donyal could exchange a library scrip for one of the available volumes.",["pending"]="{actor} would present a library scrip to Donyal.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} exchanged a library scrip for a book.",["reviewStatus"]="AUTHOR_SOURCE_REVIEWED_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="6bc8db827670a0ea12034f41877240cdf25df0cc7eff18f22225627d183863a1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentPlayability","unlistedQuantities"}},
[580]={["atomIDs"]={"580:description:1-112","580:description:115-161","580:description:166-205","580:description:208-302","580:description:307-372","580:description:375-421","580:description:424-508","580:objective:1-91"},["opening"]="Whiskey Slim had opened the captain's captured port during a storm off the Hinterlands, only for a wave to sweep the bottles overboard. Recovering them offered escape from the punishment he expected.",["pending"]="{actor} intended to recover the lost Pupellyverbos Port for Whiskey Slim.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the lost bottles of Pupellyverbos Port to Whiskey Slim.",["sourceClassMask"]="?",["sourceHash"]="260884fa95aa1c7d5f9092c2f4f8e7827b67357737b6a6969a1823c5a8e148eb",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[581]={["atomIDs"]={"581:description:1-17","581:description:20-62","581:description:65-242","581:description:245-331","581:description:336-378","581:description:383-430","581:description:433-463","581:description:466-501","581:objective:1-62"},["opening"]="Nimboya had returned from Orgrimmar to find his chief's youngest son. Yenniku had been left among the Gurubashi before the Darkspear departure with Thrall; Nimboya now suspected the northern Bloodscalps held him.",["pending"]="{actor} meant to bring nine Bloodscalp Tusks to Nimboya.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered nine Bloodscalp Tusks to Nimboya.",["sourceClassMask"]="?",["sourceHash"]="ce83dfcc0bb09827f504c714be4cd3583488eb8f6416bfbbf300b10f3bf824d8",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[582]={["atomIDs"]={"582:description:1-32","582:description:37-108","582:description:111-214","582:description:219-335","582:description:349-447","582:objective:1-61"},["bridge"]="The tusk collection had begun the Bloodscalp search without settling Yenniku's fate. Nimboya now wanted shrunken heads from their headhunters so he could look for the missing boy among their victims.",["bridgeFrom"]=581,["bridgeReplacesSetup"]=true,["opening"]="Nimboya needed to know whether Yenniku had been killed. He requested shrunken heads from Bloodscalp headhunters at the northern ruins so he could search their trophies for the missing son.",["pending"]="{actor} planned to gather twenty Shrunken Heads for Nimboya's inspection.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered twenty Shrunken Heads to Nimboya.",["sourceClassMask"]="?",["sourceHash"]="fbfa183d1629aee19f41fa3d4d844f3d407b66b7560ca28cd0cdc7af5ca98fcb",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[583]={["atomIDs"]={"583:description:1-25","583:description:30-188","583:description:191-310","583:description:315-407","583:description:412-433","583:description:436-481","583:objective:1-27"},["opening"]="Barnil introduced the camp's most celebrated hunter: Hemet Nesingwary, an Alliance veteran with a taste for big game. He thought a seasoned visitor might find instruction despite Hemet's reserve toward strangers.",["pending"]="{actor} intended to speak with Hemet Nesingwary.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Hemet Nesingwary.",["sourceClassMask"]="?",["sourceHash"]="1cee3b603eefbbbd933d95806f1b2d0d04ffd3ba0735ccc6072752765ca442f2",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[584]={["atomIDs"]={"584:description:1-70","584:description:73-108","584:description:113-206","584:description:209-327","584:description:332-421","584:description:426-456","584:description:459-506","584:objective:1-94"},["bridge"]="Yenniku was not among the heads Nimboya examined. To learn more, he demanded the heads of Gan'zulah and Nezzliok from Zul'Kunda, intending to bind their knowledge within his cauldron.",["bridgeFrom"]=582,["bridgeReplacesSetup"]=true,["opening"]="Yenniku was absent from the collected heads, but still missing. Nimboya turned toward the chief and witchdoctor at Zul'Kunda, intending to bind their severed heads in a cauldron and force the knowledge they would not willingly give.",["pending"]="{actor} intended to bring Gan'zulah's Head and Nezzliok's Head to the Bubbling Cauldron.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Gan'zulah's Head and Nezzliok's Head to the Bubbling Cauldron at Grom'gol.",["sourceClassMask"]="?",["sourceHash"]="e9d26228ac83c8551cd8871dbc2c024f86490287b9c409000ae2c9154982c0ad",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[585]={["atomIDs"]={"585:description:1-30","585:description:35-45","585:description:48-98","585:description:101-183","585:description:188-231","585:description:234-384","585:description:387-493","585:objective:1-119"},["opening"]="Nezzliok's bound spirit claimed knowledge of Yenniku but demanded appeasement. Three trophy skulls from rival Skullsplitter settlements were to become slaves to his spirit in the Nether.",["pending"]="{actor} meant to obtain trophies from Balia'mah, Ziata'jai and Zul'Mamwe for the cauldron.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the three named Skullsplitter trophies to the Bubbling Cauldron.",["sourceClassMask"]="?",["sourceHash"]="026140aa688987c30dadb574bd4eee0643943d2e459d258dedb7c1d9ee2714af",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[586]={["atomIDs"]={"586:description:1-31","586:description:36-45","586:description:48-73","586:description:78-150","586:description:152-159","586:description:164-227","586:description:230-340","586:description:343-346","586:description:349-388","586:description:393-464","586:objective:1-90","586:objective:95-180"},["opening"]="Gan'zulah answered binding with rage and a demand for revenge. He sent the undertaking against the Skullsplitters' fiercest fighters and their chief Ana'thek, requiring the chief's broken armor as proof.",["pending"]="{actor} would fulfill the specified Skullsplitter assignment and recover Ana'thek's Broken Armor.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against eight Hunters, six Headhunters and four Berserkers and delivered Ana'thek's Broken Armor to the cauldron.",["sourceClassMask"]="?",["sourceHash"]="37e95fce3c13be9039740bf74fc1fa35bacdb33750da333f20b18d85024c7358",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[587]={["atomIDs"]={"587:description:1-17","587:description:20-74","587:description:79-167","587:description:170-227","587:description:232-346","587:description:349-413","587:description:418-488","587:objective:1-60"},["opening"]="Deeg found Booty Bay's snuff supply exhausted after Bloodsails hijacked the herbalist's shipment. His search for familiar comforts in port became a request to reclaim fifteen shares.",["pending"]="{actor} meant to obtain fifteen shares of Snuff for Deeg.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered fifteen shares of Snuff to Deeg.",["sourceClassMask"]="?",["sourceHash"]="9e8caa1422933fa0450ffa215c0aa3f9f863dd4beebf2cff3a2019b89ccb8dcb",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[588]={["aftermath"]="Kin'weelay regarded rescue from Zanzil as a very faint hope. He did not dismiss that hope, leaving a possible magical answer to pursue.",["atomIDs"]={"588:description:1-18","588:description:23-114","588:description:119-152","588:description:157-207","588:description:210-299","588:description:304-336","588:description:341-410","588:description:413-430","588:objective:1-22"},["endingAtomIDs"]={"588:completion:1-20","588:completion:25-134","588:completion:136-141","588:completion:143-174","588:completion:179-200"},["opening"]="Nezzliok finally named Zanzil the Outcast as Yenniku's captor. He claimed the witchdoctor controlled the boy in body and soul; the search turned to Kin'weelay for magic strong enough to offer release.",["pending"]="{actor} intended to consult Kin'weelay about Yenniku.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Kin'weelay about Yenniku's fate.",["sourceClassMask"]="?",["sourceHash"]="6069b2a17e6038a0bb2aa00f4de0f36b712abd39bbfb2ab79cdd3866e25b3870",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[589]={["atomIDs"]={"589:description:1-67","589:description:70-120","589:description:123-217","589:description:222-290","589:description:293-414","589:description:417-501","589:objective:1-68"},["opening"]="Kin'weelay proposed the legendary Mind's Eye as a possible means of saving Yenniku. While he sought its location through the spirits, three rare blue shards from Crystalvein's Ironjaw Basilisks would supply the magic to bend it.",["pending"]="{actor} planned to gather three Pulsing Blue Shards for Kin'weelay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered three Pulsing Blue Shards to Kin'weelay.",["sourceClassMask"]="?",["sourceHash"]="f8f7e59cdf306fa4f6429072e15d0d989501a2539919e918fbfa9c39753183e7",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[590]={["aftermath"]="Calvin admitted that he had expected an easy opponent. He offered less coin than promised and acknowledged that his earlier promise had been a lie.",["atomIDs"]={"590:description:1-5","590:description:10-15","590:description:20-34","590:description:36-61","590:description:66-72","590:description:74-85","590:description:87-111","590:description:113-130","590:description:132-145","590:description:147-166","590:objective:1-37"},["availabilityQualification"]={["basis"]="Catalog states positive beta server experience; confirms reported definition, not that a player can reach its giver in the target release",["currentServerPlayableConfirmed"]=false,["eligibility"]="BETA_SERVER_DEFINED_PUBLISHER_CLAIM",["sourceReceipt"]="https://www.curseforge.com/wow/addons/questdb/files/9014639 ; https://tierhall.app/wow/quests/590 ; https://warcraftforever.games/quests/590 ; https://wowfwiki.com/wiki/Quests"},["endingAtomIDs"]={"590:completion:1-11","590:completion:13-23","590:completion:28-58","590:completion:60-80","590:completion:85-113","590:completion:115-204"},["opening"]="Calvin Montague denied owing money and brushed aside the mention of a letter. The demand became a challenge to fight in Deathknell.",["pending"]="{actor} meant to defeat Calvin Montague in Deathknell.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} defeated Calvin Montague in the Deathknell challenge.",["sourceClassMask"]="?",["sourceHash"]="f03dc0df44aca5532e74996eb84bbcd49709444567a2b0a5b226bd96e951d46c",["sourceMapID"]="1420",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[591]={["aftermath"]="Kin'weelay prepared a ritual to reshape the recovered Eye. He inferred Mai'Zoth's defeat from its recovery and worried about the ogre's influence in the spirit realm; that concern remained his interpretation.",["atomIDs"]={"591:description:1-93","591:description:96-116","591:description:119-218","591:description:223-290","591:description:295-351","591:description:354-426","591:objective:1-61"},["bridge"]="The blue shards had reached Kin'weelay while his spirit inquiry located the Eye. Mai'Zoth held it deep within the Mosh'Ogg mound, and recovering it became the next hope for Yenniku.",["bridgeFrom"]=589,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"591:completion:1-22","591:completion:24-62","591:completion:67-149","591:completion:151-203","591:completion:208-346","591:completion:351-387","591:completion:389-455"},["opening"]="The spirit inquiry led Kin'weelay to Mai'Zoth in the Mosh'Ogg mound. He remembered the ogre mage's viciousness and strong magic, now strengthened further by the Mind's Eye that Yenniku's rescue required.",["pending"]="{actor} would recover the Mind's Eye from Mai'Zoth for Kin'weelay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Mind's Eye to Kin'weelay.",["sourceClassMask"]="?",["sourceHash"]="dbea9356b56ebe9fa2f06b3f5891c456c1af08dfdb7bff8610613199626dd308",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[592]={["aftermath"]="Nimboya declared Yenniku freed from Zanzil's will. The completed rescue answered the desperate search that had begun with uncertainty over whether the boy still lived.",["atomIDs"]={"592:description:1-47","592:description:50-165","592:description:170-200","592:description:205-329","592:objective:1-37"},["bridge"]="The Mind's Eye had reached Kin'weelay and been reshaped into a Soul Gem. The rescue now required finding Yenniku with Zanzil at Aboraz and bringing his captured soul to Nimboya.",["bridgeFrom"]=591,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"592:completion:1-15","592:completion:17-116","592:completion:121-233"},["opening"]="Kin'weelay had reshaped the Eye into a Soul Gem. At the distant Ruins of Aboraz, it was to stun Yenniku and capture his soul, which Nimboya would then receive within the filled gem.",["pending"]="{actor} intended to use the Soul Gem on Yenniku and take the filled gem to Nimboya.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the Filled Soul Gem to Nimboya after completing the Yenniku assignment.",["sourceClassMask"]="?",["sourceHash"]="faa08c9a3deb08bc1a51f046c5d7131236a7502a4c89400a09ba7e167bd75a48",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[594]={["atomIDs"]={"594:description:1-43","594:description:48-70","594:description:75-107","594:description:109-172","594:description:177-364","594:description:369-417","594:objective:1-43"},["opening"]="A bottle carried a plea from someone held by a great Skymane. Unfamiliar stars gave little help, but the writer described Wild Shore to the northwest and ships to the southwest as clues to the island prison.",["pending"]="{actor} meant to find the author of the bottled message.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Princess Poobah, the message's author.",["sourceClassMask"]="?",["sourceHash"]="c49d669eeb196e93de971ff8ca5c6973a02b5330b204cb62a1e0a3b776c2b9db",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[595]={["atomIDs"]={"595:description:1-35","595:description:38-152","595:description:157-320","595:description:325-390","595:description:393-415","595:description:420-503","595:objective:1-64"},["opening"]="Crazz needed a scout while the Blackwater crew occupied itself in port. Their Bloodsail rivals had been sighted across southern Stranglethorn, and the cove north of Booty Bay was the place to begin looking.",["pending"]="{actor} intended to investigate the cove north of Booty Bay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Crazz's scouting assignment at the northern cove.",["sourceClassMask"]="?",["sourceHash"]="5d4e28adfa8adbebde7f766891c347af3a68ae86301a8de40ac23e403f93d8c3",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[596]={["atomIDs"]={"596:description:1-59","596:description:61-94","596:description:99-141","596:description:144-203","596:description:206-250","596:description:255-278","596:description:281-350","596:description:353-396","596:objective:1-71"},["opening"]="Kin'weelay's presence at Grom'gol served more than the search for Yenniku. He considered trophies a source of power over enemies and asked for necklaces from the Darkspears' old Bloodscalp foes.",["pending"]="{actor} meant to gather twenty-five Bloody Bone Necklaces.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered twenty-five Bloody Bone Necklaces to Kin'weelay.",["sourceClassMask"]="?",["sourceHash"]="19ac1d1a04d8b50e44859e48625bf7f48dbef9586ee4c2ff7baccec4d6de0cf9",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[597]={["atomIDs"]={"597:description:1-93","597:description:98-122","597:description:127-188","597:description:191-258","597:description:261-297","597:objective:1-54"},["opening"]="The map marked this very position as a camp outside Booty Bay. Its orders demanded silence until the southern command gave the signal for attack, making the discovered papers urgent news for Crazz.",["pending"]="{actor} planned to report the map and attack orders to Crazz.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the discovered Bloodsail plans to First Mate Crazz.",["sourceClassMask"]="?",["sourceHash"]="7041c880a7ee51079df71563610d1e89c1e5833448484b0b030a862914b32cbb",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[598]={["atomIDs"]={"598:description:1-76","598:description:79-174","598:description:177-287","598:description:292-305","598:description:308-358","598:description:361-430","598:objective:1-70"},["opening"]="Kin'weelay turned from Bloodscalp trophies to the Skullsplitters in the southeast. The Darkspears had left Stranglethorn, but he regarded the old conflict as binding them still.",["pending"]="{actor} planned to recover twenty-five Split Bone Necklaces for Kin'weelay.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered twenty-five Split Bone Necklaces to Kin'weelay.",["sourceClassMask"]="?",["sourceHash"]="5e8493936f3ac375832d7b04d2fc0b710ab191501020fc37d5c37ad315594d2b",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[599]={["atomIDs"]={"599:description:1-18","599:description:21-94","599:description:97-131","599:description:134-188","599:description:193-222","599:description:225-285","599:description:288-331","599:objective:1-60"},["bridge"]="The cove report had reached Crazz. What looked like rival activity now appeared to be an attack plan against Booty Bay, requiring Fleet Master Seahorn's attention.",["bridgeFrom"]=597,["bridgeReplacesSetup"]=true,["opening"]="Crazz understood the cove's evidence as a planned assault on Booty Bay. The threat exceeded a routine scout report and needed to reach Fleet Master Seahorn immediately.",["pending"]="{actor} meant to report the planned attack to Fleet Master Seahorn.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the planned Bloodsail attack to Fleet Master Seahorn.",["sourceClassMask"]="?",["sourceHash"]="92230b405d926e91e63fa5a9e0ff6975b3d23265ebebcaf0873e989c2f8b108e",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[600]={["atomIDs"]={"600:description:1-136","600:description:139-163","600:description:168-236","600:description:239-374","600:description:379-461","600:description:466-471","600:description:479-511","600:objective:1-63"},["opening"]="Crank resented the Venture Company's hold over Stranglethorn's crystal trade. Basilisks barred the miners from Crystalvein itself, but the nearby hills still supplied crystals he wanted taken from their operation.",["pending"]="{actor} planned to recover ten Singing Blue Crystals from the Venture Company.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered ten Singing Blue Crystals to Crank Fizzlebub.",["sourceClassMask"]="?",["sourceHash"]="87f821a4791ba01f24c2dbea04fa5c04a05332aec2ac3c2f263103b7a3ae111b",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[601]={["atomIDs"]={"601:description:1-123","601:description:125-229","601:description:234-283","601:description:285-382","601:description:384-448","601:objective:1-66"},["opening"]="Revilgaz linked the island's elementals to Gazban and the Stone's reputed curse of fading from existence. Bracers carrying magical residue might let a Dalaran mage examine a way around that curse.",["pending"]="{actor} intended to recover six Water Elemental Bracers for Revilgaz.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered six Water Elemental Bracers to Baron Revilgaz.",["sourceClassMask"]="?",["sourceHash"]="70efcfa2a4babe84f7a2ca5416e323b531b155a2fbf0fae61680315eebb2c069",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[602]={["atomIDs"]={"602:description:1-183","602:description:185-259","602:description:264-359","602:description:362-416","602:description:419-472","602:objective:1-76"},["bridge"]="The bracers had reached Revilgaz, carrying the magical residue he wanted examined. He sent them to Ansirem Runeweaver in Dalaran for an answer about the Stone's curse.",["bridgeFrom"]=601,["bridgeReplacesSetup"]=true,["opening"]="The bracers were bound for magical analysis. Revilgaz recommended Ansirem Runeweaver, whose knowledge he trusted, while acknowledging that Dalaran's mages were occupied with rebuilding their city.",["pending"]="{actor} planned to take the water elemental bracers to Ansirem in Dalaran.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the water elemental bracers to Archmage Ansirem Runeweaver.",["sourceClassMask"]="?",["sourceHash"]="902b8eab768232a6ff437f726a2cc134acc1ab0568cfc68c886b4526be0bb7d8",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[603]={["atomIDs"]={"603:description:1-95","603:description:97-118","603:description:120-171","603:description:176-252","603:description:254-272","603:description:274-288","603:description:293-447","603:objective:1-29"},["bridge"]="The magical inquiry had reached Ansirem. He identified an altar as the Stone's focus and proposed an ancient dagger to disrupt it, but the relic had gone with his daughter to Booty Bay.",["bridgeFrom"]=602,["bridgeReplacesSetup"]=true,["opening"]="Ansirem identified an altar as the focus amplifying the Stone's power. An ancient troll dagger could overpower it, but he had given that relic to his daughter Catelyn, who left for a pirate's life in Booty Bay.",["pending"]="{actor} meant to speak with Catelyn the Blade about the dagger.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} spoke with Catelyn the Blade in Booty Bay.",["sourceClassMask"]="?",["sourceHash"]="6cdd8041611608e6b9a26b0c67c32d990b595caf5cfaf59fc49d577738b68781",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[604]={["atomIDs"]={"604:description:1-65","604:description:68-141","604:description:146-252","604:description:255-274","604:description:277-330","604:description:333-379","604:objective:1-140"},["bridge"]="The warning had reached Seahorn. He ordered a raid on the Bloodsail command post at Wild Shore, with charts and written orders needed to reveal the plan in detail.",["bridgeFrom"]=599,["bridgeReplacesSetup"]=true,["opening"]="Seahorn ordered a raid on the Bloodsails' southern command post at Wild Shore. Their charts and written orders could expose the attack in detail, while ten swashbucklers formed the combat assignment.",["pending"]="{actor} would recover the Bloodsail Charts and Orders while meeting the swashbuckler assignment.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the assignment against ten Bloodsail Swashbucklers and delivered the Charts and Orders to Seahorn.",["sourceClassMask"]="?",["sourceHash"]="dceb9f0698c23c617a64397ff54a919be9b30d00a486129cd7f8a3023b7fa830",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[605]={["atomIDs"]={"605:description:1-91","605:description:94-218","605:description:223-243","605:description:248-294","605:description:297-395","605:description:400-511","605:objective:1-51"},["opening"]="Crank saw a market for Stranglethorn's unique singing crystals. Basilisks ate the stone and sometimes carried usable shards in their hardened skin, offering an alternative to the Venture Company's mining.",["pending"]="{actor} intended to gather ten Singing Crystal Shards for Crank.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered ten Singing Crystal Shards to Crank Fizzlebub.",["sourceClassMask"]="?",["sourceHash"]="3e653e714b781919892e1c75d9a6bd3dc303125cc5fcb0a6c670c380622ac224",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[606]={["atomIDs"]={"606:description:1-83","606:description:86-126","606:description:128-157","606:description:162-211","606:description:214-272","606:description:275-313","606:description:318-365","606:description:368-425","606:description:428-493","606:objective:1-58"},["opening"]="MacKinley wanted Shaky's gambling debt collected through fear. Gorilla giblets would make the threat appear worse than it was, provided their animal origin stayed concealed.",["pending"]="{actor} meant to bring five Mistvale Giblets to Shaky Phillipe.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered five Mistvale Giblets to Shaky Phillipe.",["sourceClassMask"]="?",["sourceHash"]="3e950ba2d86cfd0df5cee6efdf58cffaeb51ec83164d4c04e881aaa49bc48bab",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[607]={["atomIDs"]={"607:description:1-46","607:description:49-85","607:description:88-96","607:description:101-173","607:description:176-222","607:objective:1-46"},["bridge"]="The giblets had reached Shaky with MacKinley's implied threat. Shaky now offered a pouch of payment and asked that his explanation accompany it back to Sea Wolf.",["bridgeFrom"]=606,["bridgeReplacesSetup"]=true,["opening"]="Shaky offered a pouch for Sea Wolf and an explanation for the delayed debt. The payment now needed to return to MacKinley without further threats.",["pending"]="{actor} planned to carry Shaky's Payment to MacKinley.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Shaky's Payment to Sea Wolf MacKinley.",["sourceClassMask"]="?",["sourceHash"]="bd446ff6fd338e64c21f7de90d77c936edec8b2b900e4a1e75cd6db98feb88f4",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[608]={["aftermath"]="Seahorn celebrated the result for the Blackwater Raiders. His response did not establish the permanent destruction of every Bloodsail force.",["atomIDs"]={"608:description:1-28","608:description:31-118","608:description:123-179","608:description:182-266","608:description:271-346","608:description:349-464","608:description:467-502","608:objective:1-115"},["bridge"]="The charts and orders had exposed the plan to Seahorn. He answered with an assignment against Stillwater, Keelhaul and Firallon at the Bloodsail landing.",["bridgeFrom"]=604,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"608:completion:1-48","608:completion:50-73"},["opening"]="With the attack plan known, Seahorn chose a strike at the Bloodsail leadership. He demanded Stillwater, Keelhaul and Firallon be removed at their landing rather than commit his whole fleet.",["pending"]="{actor} intended to undertake the assignment against the three Bloodsail leaders.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the assignment against Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.",["sourceClassMask"]="?",["sourceHash"]="875baa463318223cd35ae31470db94075e45069c13841becce0783bea75c16e1",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[609]={["aftermath"]="MacKinley saw resale value in the recovered belongings, especially the contents of Maury's foot. His warning returned to the debts and the danger of gambling with the wrong people.",["atomIDs"]={"609:description:1-61","609:description:66-148","609:description:153-251","609:description:254-329","609:description:332-388","609:description:393-467","609:description:470-492","609:objective:1-115"},["endingAtomIDs"]={"609:completion:1-6","609:completion:8-83","609:completion:85-100","609:completion:105-190","609:completion:195-281"},["opening"]="Three more gamblers owed MacKinley months of debt. Reports placed them cursed among the Aboraz and Jubuwal ruins, but their condition did not lessen his demand for the belongings he named as payment.",["pending"]="{actor} intended to recover Maury's Clubbed Foot, Jon-Jon's Golden Spyglass and Chucky's Huge Ring.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the three named debt trophies to Sea Wolf MacKinley.",["sourceClassMask"]="?",["sourceHash"]="bf2663932abf0b75b14ac2e7d0e813af536676088dd33c879837d85355677deb",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[610]={["atomIDs"]={"610:description:1-19","610:description:21-86","610:description:91-284","610:description:289-396","610:description:398-462","610:objective:1-46"},["opening"]="Catelyn had rejected the quiet life her father expected, but her dagger had since passed to a Bloodsail pirate. Pretty Boy Duncan now held the relic needed for the Stone's altar.",["pending"]="{actor} meant to retrieve Catelyn's dagger from Pretty Boy Duncan.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the recovery of Catelyn's dagger from Pretty Boy Duncan.",["sourceClassMask"]="?",["sourceHash"]="d4c77f34bb6ff8396764e90e11e0a0c7b7a5c85ccac2754133ced7e9ac65d17a",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[611]={["aftermath"]="Revilgaz planned a prominent place for the Stone among his troll artifacts. He admired the tide-like appearance within it, treating the dangerous relic as a collector's prize.",["atomIDs"]={"611:description:1-44","611:description:46-179","611:description:181-207","611:description:212-272","611:description:274-309","611:objective:1-141"},["bridge"]="The dagger had been recovered from Duncan. Catelyn lent it for a search near the sunken troll ruins, with the altar, Gazban and the Stone of the Tides forming the remaining assignment.",["bridgeFrom"]=610,["bridgeReplacesSetup"]=true,["endingAtomIDs"]={"611:completion:1-8","611:completion:10-28","611:completion:30-109","611:completion:111-189","611:completion:191-202"},["opening"]="Catelyn lent the recovered blade and suggested the sunken troll city near the island. The assignment joined the altar's destruction to Gazban's defeat, with both the Stone and borrowed knife due to Revilgaz.",["pending"]="{actor} planned to destroy the Altar of the Tides, confront Gazban and return the Stone and Blade.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the altar-and-Gazban assignment and delivered the Stone of the Tides and Catelyn's Blade to Revilgaz.",["sourceClassMask"]="?",["sourceHash"]="f08606837ac3cb06b8fa0bd25265ba98cc171d4ce301427d7293b9569dd21970",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}
}
